import { Input, Select, TextArea } from './components/Input';
import { 
  Calendar, User, MapPin, Hash, Map, Building2, 
  Phone, Download, Printer, CreditCard, Plus, Trash2, Tag, Percent, Search,
  Mail, MessageCircle, FileText, Sparkles, Loader2, Barcode,
  Users, UserPlus, ExternalLink, Share2, RotateCcw, AlertTriangle, X, PackagePlus, List
} from 'lucide-react';
import Fuse from 'fuse.js';
import JsBarcode from 'jsbarcode';

const STORAGE_KEY = 'belconfort_receipt_data';
const TEAM_STORAGE_KEY = 'belconfort_team_list';
const CUSTOM_CATALOG_KEY = 'belconfort_custom_catalog';

// Barcode Component for Preview
const BarcodePreview = ({ code }: { code: string }) => {
  const imgRef = useRef<HTMLImageElement>(null);

  useEffect(() => {
    if (imgRef.current && code) {
      try {
        const canvas = document.createElement('canvas');
        JsBarcode(canvas, code, {
          format: "CODE128",
          width: 1, 
          height: 30,
          displayValue: false,
          margin: 0,
          background: 'transparent',
          lineColor: '#000000'
        });
        imgRef.current.src = canvas.toDataURL();
      } catch(e) { /* ignore */ }
    }
  }, [code]);

  if (!code) return null;
  return <img ref={imgRef} alt="barcode" className="h-2.5 w-auto max-w-full object-contain opacity-80 mix-blend-multiply mt-0.5" />;
}

export default function App() {
  // Initialize state from localStorage or default
  const [data, setData] = useState<ReceiptData>(() => {
    try {
      const savedData = localStorage.getItem(STORAGE_KEY);
      if (savedData) {
        return { ...INITIAL_DATA, ...JSON.parse(savedData) };
      }
    } catch (error) {}
    return INITIAL_DATA;
  });

  const [salespeople, setSalespeople] = useState<string[]>(() => {
    try {
      const savedTeam = localStorage.getItem(TEAM_STORAGE_KEY);
      if (savedTeam) return JSON.parse(savedTeam);
    } catch (error) {}
    return ['ROBSON', 'SARA'];
  });

  const [customCatalog, setCustomCatalog] = useState<CatalogItem[]>(() => {
    try {
      const saved = localStorage.getItem(CUSTOM_CATALOG_KEY);
      if (saved) return JSON.parse(saved);
    } catch (error) {}
    return [];
  });

  // UI State
  const [activeTab, setActiveTab] = useState<'manual' | 'import' | 'team' | 'catalog'>('manual');
  const [importText, setImportText] = useState("");
  const [isImporting, setIsImporting] = useState(false);
  const [importError, setImportError] = useState<{title: string, msg: string} | null>(null);

  // New Product Catalog Form State
  const [catCategory, setCatCategory] = useState("");
  const [catProduct, setCatProduct] = useState("");
  const [catHeight, setCatHeight] = useState("");
  const [catSize, setCatSize] = useState("");
  const [catColor, setCatColor] = useState("");
  const [catPrice, setCatPrice] = useState("");

  // Temporary state for adding a product to cart
  const [selectedProduct, setSelectedProduct] = useState("");
  const [selectedPrice, setSelectedPrice] = useState("");
  const [selectedQuantity, setSelectedQuantity] = useState("1");
  const [searchTerm, setSearchTerm] = useState("");
  const [isSearchOpen, setIsSearchOpen] = useState(false);
  const [discountInput, setDiscountInput] = useState("");

  // Merge catalogs and update Fuse
  const fullCatalog = useMemo(() => {
    const combined = [...PRODUCT_CATALOG, ...customCatalog];
    return combined.sort((a, b) => a.name.localeCompare(b.name));
  }, [customCatalog]);

  const fullProductList = useMemo(() => fullCatalog.map(p => p.name), [fullCatalog]);

  const fuseInstance = useMemo(() => new Fuse(fullProductList, {
    includeScore: true,
    threshold: 0.4,
    ignoreLocation: true,
  }), [fullProductList]);

  useEffect(() => {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(data));
  }, [data]);

  useEffect(() => {
    localStorage.setItem(TEAM_STORAGE_KEY, JSON.stringify(salespeople));
  }, [salespeople]);

  useEffect(() => {
    localStorage.setItem(CUSTOM_CATALOG_KEY, JSON.stringify(customCatalog));
  }, [customCatalog]);

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement>) => {
    const { name, value } = e.target;
    setData(prev => ({ ...prev, [name]: value }));
  };

  const handleAddCustomProduct = () => {
    if (!catCategory.trim() || !catProduct.trim() || !catPrice.trim()) {
      alert("Preencha ao menos Categoria, Produto e Preço.");
      return;
    }

    const priceValue = parseFloat(catPrice.replace('.', '').replace(',', '.') || "0");
    // Format: CATEGORIA PRODUTO ALTURA TAMANHO COR
    const fullName = `${catCategory} ${catProduct} ${catHeight} ${catSize} ${catColor}`.replace(/\s+/g, ' ').trim().toUpperCase();

    if (fullProductList.includes(fullName)) {
      alert("Este produto já existe no catálogo!");
      return;
    }

    const newItem: CatalogItem = { name: fullName, price: priceValue };
    setCustomCatalog(prev => [...prev, newItem]);

    // Reset form
    setCatCategory("");
    setCatProduct("");
    setCatHeight("");
    setCatSize("");
    setCatColor("");
    setCatPrice("");
    alert("Produto adicionado ao catálogo com sucesso!");
  };

  const handleRemoveCustomProduct = (name: string) => {
    if (window.confirm("Remover este produto do catálogo personalizado?")) {
      setCustomCatalog(prev => prev.filter(p => p.name !== name));
    }
  };

  const filteredProducts = searchTerm
    ? fuseInstance.search(searchTerm).map(result => result.item)
    : fullProductList;

  const handleSearchSelect = (name: string) => {
    setSelectedProduct(name);
    setSearchTerm(name);
    setIsSearchOpen(false);
    const item = fullCatalog.find(p => p.name === name);
    if (item) setSelectedPrice(item.price.toFixed(2).replace('.', ','));
  };

  const handleAddProduct = () => {
    if (!selectedProduct) return;
    const priceValue = parseFloat(selectedPrice.replace('.', '').replace(',', '.') || "0");
    const quantityValue = parseInt(selectedQuantity) || 1;
    const pseudoCode = Math.floor(100000 + Math.random() * 900000).toString();

    setData(prev => ({
      ...prev,
      products: [...prev.products, {
        code: pseudoCode,
        name: selectedProduct,
        price: priceValue,
        quantity: quantityValue,
        warrantyTime: "",
        warrantyUnit: "MESES"
      }]
    }));

    setSelectedProduct("");
    setSearchTerm("");
    setSelectedPrice("");
    setSelectedQuantity("1");
  };

  const handleSmartImport = async () => {
    if (!importText.trim()) return;
    setIsImporting(true);
    setImportError(null);
    try {
      const result = await parseReceiptFromText(importText, fullProductList);
      let updatedProducts = [...data.products];
      if (result.items && Array.isArray(result.items)) {
        result.items.forEach((item: { name: string, quantity: number }) => {
            const systemProduct = fullCatalog.find(p => p.name === item.name);
            if (systemProduct) {
                const quantityToAdd = item.quantity || 1;
                const existingIdx = updatedProducts.findIndex(p => p.name === systemProduct.name);
                if (existingIdx >= 0) {
                    updatedProducts[existingIdx].quantity += quantityToAdd;
                } else {
                    updatedProducts.push({
                        code: Math.floor(100000 + Math.random() * 900000).toString(),
                        name: systemProduct.name,
                        price: systemProduct.price,
                        quantity: quantityToAdd,
                        warrantyTime: "",
                        warrantyUnit: "MESES"
                    });
                }
            }
        });
      }
      setData(prev => ({ ...prev, ...result.clientData, products: updatedProducts }));
      setImportText("");
      setActiveTab('manual');
    } catch (error: any) {
      setImportError({ title: "Erro na IA", msg: error.message });
    } finally {
      setIsImporting(false);
    }
  };

  const subtotal = data.products.reduce((acc, curr) => acc + (curr.price * curr.quantity), 0);
  const manualDiscount = data.discountType === 'fixed' ? data.discountValue : subtotal * (data.discountValue / 100);
  const totalValue = Math.max(0, subtotal - manualDiscount);

  return (
    <div className="min-h-screen bg-gray-950 text-gray-100 font-sans pb-20">
      <header className="border-b border-gray-800 bg-[#0047AB] shadow-lg sticky top-0 z-50">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 h-20 flex items-center justify-between">
          <div>
            <h1 className="text-3xl font-serif font-bold text-white">BelConfort</h1>
            <p className="text-blue-100 text-[10px] tracking-[0.2em] uppercase">Camas e Móveis</p>
          </div>
          <span className="text-[10px] px-2 py-1 bg-white/10 rounded-full text-white border border-white/20">v1.8.0</span>
        </div>
      </header>

      <main className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
        <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">
          <div className="lg:col-span-5 space-y-6">
            <div className="flex p-1 space-x-1 bg-gray-900 rounded-xl border border-gray-800 overflow-x-auto">
                {[
                  { id: 'manual', icon: FileText, label: 'Venda' },
                  { id: 'catalog', icon: PackagePlus, label: 'Catálogo' },
                  { id: 'import', icon: Sparkles, label: 'IA' },
                  { id: 'team', icon: Users, label: 'Equipe' }
                ].map(tab => (
                  <button
                    key={tab.id}
                    onClick={() => setActiveTab(tab.id as any)}
                    className={`flex-1 flex items-center justify-center gap-2 py-2.5 px-4 text-xs font-medium rounded-lg transition-all min-w-fit ${
                      activeTab === tab.id ? 'bg-blue-600 text-white shadow-lg' : 'text-gray-400 hover:text-gray-200 hover:bg-gray-800'
                    }`}
                  >
                    <tab.icon className="w-4 h-4" />
                    {tab.label}
                  </button>
                ))}
            </div>

            {/* Catalog Tab */}
            {activeTab === 'catalog' && (
              <div className="space-y-6 animate-in fade-in slide-in-from-bottom-2 duration-300">
                <div className="bg-gray-900 border border-gray-800 rounded-2xl p-6 shadow-xl">
                  <h2 className="text-lg font-semibold text-white flex items-center gap-2 mb-6">
                    <span className="w-1 h-6 bg-indigo-500 rounded-full"></span>
                    CADASTRAR PRODUTO
                  </h2>
                  <div className="space-y-4">
                    <Input label="Categoria" value={catCategory} onChange={e => setCatCategory(e.target.value)} placeholder="Ex: COLCHÃO" icon={<Tag className="w-4 h-4"/>}/>
                    <Input label="Produto" value={catProduct} onChange={e => setCatProduct(e.target.value)} placeholder="Ex: AIRTECH SPRINGPOCKET" icon={<Barcode className="w-4 h-4"/>}/>
                    <div className="grid grid-cols-2 gap-4">
                      <Input label="Altura" value={catHeight} onChange={e => setCatHeight(e.target.value)} placeholder="Ex: 30CM"/>
                      <Input label="Tamanho" value={catSize} onChange={e => setCatSize(e.target.value)} placeholder="Ex: QUEEN"/>
                    </div>
                    <div className="grid grid-cols-2 gap-4">
                      <Input label="Cor" value={catColor} onChange={e => setCatColor(e.target.value)} placeholder="Ex: BEGE"/>
                      <Input label="Preço Sugerido (R$)" value={catPrice} onChange={e => setCatPrice(e.target.value)} placeholder="0,00" icon={<CreditCard className="w-4 h-4"/>}/>
                    </div>
                    <button 
                      onClick={handleAddCustomProduct}
                      className="w-full bg-indigo-600 hover:bg-indigo-700 text-white font-bold py-3 rounded-lg flex items-center justify-center gap-2 transition-all shadow-lg shadow-indigo-900/20"
                    >
                      <Plus className="w-5 h-5"/> SALVAR NO CATÁLOGO
                    </button>
                  </div>
                </div>

                <div className="bg-gray-900 border border-gray-800 rounded-2xl p-6 shadow-xl">
                  <h2 className="text-sm font-bold text-gray-400 uppercase tracking-widest mb-4 flex items-center gap-2">
                    <List className="w-4 h-4"/> MEUS PRODUTOS ({customCatalog.length})
                  </h2>
                  <div className="space-y-2 max-h-[400px] overflow-y-auto pr-2 custom-scrollbar">
                    {customCatalog.map((item, i) => (
                      <div key={i} className="bg-gray-800 p-3 rounded-lg border border-gray-700 flex justify-between items-center group hover:border-indigo-500 transition-colors">
                        <div className="flex-1 truncate pr-4">
                          <p className="text-xs font-bold text-white uppercase truncate">{item.name}</p>
                          <p className="text-[10px] text-green-400 font-mono">{item.price.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' })}</p>
                        </div>
                        <button onClick={() => handleRemoveCustomProduct(item.name)} className="p-2 text-gray-500 hover:text-red-400 hover:bg-red-400/10 rounded transition-colors">
                          <Trash2 className="w-4 h-4" />
                        </button>
                      </div>
                    ))}
                    {customCatalog.length === 0 && <p className="text-center text-gray-500 text-xs py-10 italic">Nenhum produto personalizado cadastrado.</p>}
                  </div>
                </div>
              </div>
            )}

            {activeTab === 'manual' && (
              <div className="space-y-6 animate-in fade-in slide-in-from-bottom-2 duration-300">
                <div className="bg-gray-900 border border-gray-800 rounded-2xl p-6 shadow-xl">
                  <h2 className="text-lg font-semibold text-white flex items-center gap-2 mb-6">
                    <span className="w-1 h-6 bg-green-500 rounded-full"></span>
                    ADICIONAR AO PEDIDO
                  </h2>
                  <div className="space-y-4">
                    <div className="relative">
                      <Input
                        label="Buscar Produto..."
                        value={searchTerm}
                        onChange={e => { setSearchTerm(e.target.value); setIsSearchOpen(true); setSelectedProduct(""); }}
                        onFocus={() => setIsSearchOpen(true)}
                        onBlur={() => setTimeout(() => setIsSearchOpen(false), 200)}
                        icon={<Search className="w-4 h-4" />}
                      />
                      {isSearchOpen && (
                        <div className="absolute z-20 w-full mt-1 bg-gray-800 border border-gray-700 rounded-lg shadow-xl max-h-60 overflow-y-auto">
                          {filteredProducts.map((p, idx) => (
                            <button key={idx} className="w-full text-left px-4 py-3 text-xs text-gray-200 hover:bg-gray-700 uppercase border-b border-gray-700/50 last:border-0" onClick={() => handleSearchSelect(p)}>
                              {p}
                            </button>
                          ))}
                        </div>
                      )}
                    </div>
                    <div className="grid grid-cols-2 gap-2">
                        <Input label="Qtd" type="number" value={selectedQuantity} onChange={e => setSelectedQuantity(e.target.value)}/>
                        <Input label="Preço" value={selectedPrice} readOnly className="bg-gray-800/50 text-gray-500"/>
                    </div>
                    <button onClick={handleAddProduct} className="w-full bg-blue-600 hover:bg-blue-700 text-white font-bold py-3 rounded-lg flex items-center justify-center gap-2 transition-all">
                        <Plus className="w-4 h-4" /> ADICIONAR AO CARRINHO
                    </button>
                  </div>

                  {data.products.length > 0 && (
                    <div className="mt-6 space-y-2 border-t border-gray-800 pt-6">
                      {data.products.map((p, idx) => (
                        <div key={idx} className="bg-gray-800 p-3 rounded-lg border border-gray-700 flex justify-between items-center">
                          <div className="flex-1 truncate pr-4">
                            <p className="text-xs text-white uppercase truncate font-bold">{p.quantity}x {p.name}</p>
                            <p className="text-[10px] text-green-400 font-mono">{(p.quantity * p.price).toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' })}</p>
                          </div>
                          <button onClick={() => setData(prev => ({...prev, products: prev.products.filter((_, i) => i !== idx)}))} className="p-2 text-gray-500 hover:text-red-400">
                            <Trash2 className="w-4 h-4" />
                          </button>
                        </div>
                      ))}
                    </div>
                  )}
                </div>

                <div className="bg-gray-900 border border-gray-800 rounded-2xl p-6 shadow-xl">
                  <h2 className="text-lg font-semibold text-white flex items-center gap-2 mb-6">
                    <span className="w-1 h-6 bg-blue-500 rounded-full"></span>
                    DADOS DO CLIENTE
                  </h2>
                  <div className="space-y-4">
                    <div className="grid grid-cols-2 gap-4">
                      <Select label="Vendedor" name="salesperson" value={data.salesperson} onChange={handleChange} options={salespeople} icon={<User className="w-4 h-4"/>}/>
                      <Input label="Código Pedido" name="saleCode" value={data.saleCode} onChange={handleChange} icon={<Barcode className="w-4 h-4"/>}/>
                    </div>
                    <Input label="Nome Completo" name="name" value={data.name} onChange={handleChange} icon={<User className="w-4 h-4"/>}/>
                    <div className="grid grid-cols-2 gap-4">
                      <Input label="Rua" name="street" value={data.street} onChange={handleChange}/>
                      <Input label="Número" name="number" value={data.number} onChange={handleChange}/>
                    </div>
                    <div className="grid grid-cols-2 gap-4">
                      <Input label="Bairro" name="neighborhood" value={data.neighborhood} onChange={handleChange}/>
                      <Input label="Cidade" name="city" value={data.city} onChange={handleChange}/>
                    </div>
                    <Select label="Pagamento" name="paymentMethod" value={data.paymentMethod} onChange={handleChange} options={["DINHEIRO", "PIX", "CARTÃO", "OUTROS"]}/>
                  </div>
                </div>
              </div>
            )}

            {activeTab === 'team' && (
              <div className="bg-gray-900 border border-gray-800 rounded-2xl p-6 shadow-xl animate-in fade-in slide-in-from-bottom-2 duration-300">
                <h2 className="text-lg font-semibold text-white flex items-center gap-2 mb-6">
                  <span className="w-1 h-6 bg-yellow-500 rounded-full"></span>
                  EQUIPE DE VENDAS
                </h2>
                <div className="space-y-4">
                  <div className="flex gap-2">
                    <Input label="Novo Vendedor" value={searchTerm} onChange={e => setSearchTerm(e.target.value)} placeholder="NOME"/>
                    <button onClick={() => { if(searchTerm){ setSalespeople([...salespeople, searchTerm.toUpperCase()]); setSearchTerm(""); }}} className="bg-blue-600 p-3 rounded-lg"><Plus/></button>
                  </div>
                  <div className="space-y-2">
                    {salespeople.map(s => (
                      <div key={s} className="bg-gray-800 p-3 rounded-lg flex justify-between items-center">
                        <span className="text-sm font-bold">{s}</span>
                        <button onClick={() => setSalespeople(salespeople.filter(v => v !== s))} className="text-red-400"><Trash2 className="w-4 h-4"/></button>
                      </div>
                    ))}
                  </div>
                </div>
              </div>
            )}
          </div>

          <div className="lg:col-span-7 space-y-6">
            <div className="bg-gray-900 border border-gray-800 rounded-2xl p-4 flex gap-3 flex-wrap justify-center">
              <button onClick={() => generateReceiptPDF(data)} className="flex-1 min-w-[150px] flex items-center justify-center gap-2 bg-blue-600 hover:bg-blue-700 text-white font-bold py-3 rounded-lg transition-all shadow-lg shadow-blue-900/20">
                <Download className="w-4 h-4"/> GERAR PDF
              </button>
              <button onClick={() => alert("WhatsApp aberto...")} className="flex-1 min-w-[150px] flex items-center justify-center gap-2 bg-green-600 hover:bg-green-700 text-white font-bold py-3 rounded-lg transition-all shadow-lg shadow-green-900/20">
                <MessageCircle className="w-4 h-4"/> WHATSAPP
              </button>
              <button onClick={() => { if(confirm("Limpar pedido?")) setData(INITIAL_DATA); }} className="flex-1 min-w-[150px] flex items-center justify-center gap-2 bg-red-600/10 hover:bg-red-600/20 text-red-500 font-bold py-3 rounded-lg border border-red-500/20 transition-all">
                <RotateCcw className="w-4 h-4"/> RESET
              </button>
            </div>

            <div className="bg-white rounded-xl shadow-2xl p-8 min-h-[800px] text-gray-900 overflow-hidden">
               <div className="border-b-4 border-blue-800 pb-4 mb-8 flex justify-between items-center">
                 <div>
                   <h1 className="text-4xl font-serif font-bold text-blue-900">BelConfort</h1>
                   <p className="text-xs tracking-widest text-blue-700 font-bold uppercase">Camas e Móveis</p>
                 </div>
                 <div className="text-right text-[10px] text-gray-500">
                   <p>CNPJ 60.190.028/0001-60</p>
                   <p>BELÉM - PARÁ</p>
                 </div>
               </div>

               <div className="grid grid-cols-2 gap-8 mb-8 text-sm">
                 <div className="space-y-1">
                   <p className="text-[10px] font-bold text-gray-400 uppercase">Cliente</p>
                   <p className="font-bold text-lg">{data.name || 'NÃO INFORMADO'}</p>
                   <p className="text-gray-600 text-xs">{data.street} {data.number} - {data.neighborhood}</p>
                 </div>
                 <div className="text-right space-y-1">
                   <p className="text-[10px] font-bold text-gray-400 uppercase">Pedido / Vendedor</p>
                   <p className="font-bold text-lg">{data.saleCode || '---'}</p>
                   <p className="text-gray-600 text-xs">{data.salesperson || 'NÃO INFORMADO'}</p>
                 </div>
               </div>

               <table className="w-full text-left mb-8 border-collapse">
                 <thead>
                   <tr className="bg-gray-100 text-[10px] font-bold uppercase text-gray-600 border-y border-gray-200">
                     <th className="py-2 px-3">Qtd</th>
                     <th className="py-2 px-3">Descrição</th>
                     <th className="py-2 px-3 text-right">Preço</th>
                     <th className="py-2 px-3 text-right">Total</th>
                   </tr>
                 </thead>
                 <tbody className="text-sm">
                   {data.products.map((p, i) => (
                     <tr key={i} className="border-b border-gray-100">
                       <td className="py-3 px-3 font-bold">{p.quantity}</td>
                       <td className="py-3 px-3 uppercase text-xs leading-tight">{p.name}</td>
                       <td className="py-3 px-3 text-right text-gray-500">{p.price.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}</td>
                       <td className="py-3 px-3 text-right font-bold">{(p.price * p.quantity).toLocaleString('pt-BR', { minimumFractionDigits: 2 })}</td>
                     </tr>
                   ))}
                   {data.products.length === 0 && (
                     <tr>
                       <td colSpan={4} className="py-10 text-center text-gray-300 italic">Nenhum produto adicionado ao comprovante.</td>
                     </tr>
                   )}
                 </tbody>
               </table>

               <div className="flex justify-end pt-4 mt-auto">
                 <div className="w-64 space-y-2">
                   <div className="flex justify-between text-sm text-gray-500">
                     <span>Subtotal:</span>
                     <span>{subtotal.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' })}</span>
                   </div>
                   <div className="flex justify-between text-xl font-bold border-t-2 border-gray-900 pt-2">
                     <span>TOTAL:</span>
                     <span className="text-blue-900">{totalValue.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' })}</span>
                   </div>
                   <p className="text-[10px] text-gray-400 text-right mt-2 uppercase">Pagamento: {data.paymentMethod || '---'}</p>
                 </div>
               </div>

               <div className="mt-20 pt-8 border-t border-dashed border-gray-300 text-center">
                 <div className="w-64 h-px bg-gray-400 mx-auto mb-2"></div>
                 <p className="text-[10px] text-gray-500 uppercase font-bold tracking-widest">Assinatura do Responsável</p>
                 <p className="text-[8px] text-gray-400 mt-4 italic">Obrigado pela preferência!</p>
               </div>
            </div>
          </div>
        </div>
      </main>
    </div>
  );
}

import React, { useState, useEffect, useRef, useMemo } from 'react';
import { INITIAL_DATA, ReceiptData, PRODUCTS_LIST, PRODUCT_CATALOG, Product, CatalogItem } from './types';
import { generateReceiptPDF, getReceiptBlob } from './services/pdfService';
import { generateClientMessage, parseReceiptFromText } from './services/geminiService';
import { Input, Select, TextArea } from './components/Input';
import { 
  Calendar, User, MapPin, Hash, Map, Building2, 
  Phone, Download, Printer, CreditCard, Plus, Trash2, Tag, Percent, Search,
  ShieldCheck, Mail, MessageCircle, FileText, Sparkles, Loader2, Barcode,
  Users, UserPlus, ExternalLink, Share2, Copy, RotateCcw, AlertTriangle, PackagePlus, List
} from 'lucide-react';
import Fuse from 'fuse.js';
import JsBarcode from 'jsbarcode';

const STORAGE_KEY = 'belconfort_receipt_data';
const TEAM_STORAGE_KEY = 'belconfort_team_list';
const CUSTOM_CATALOG_KEY = 'belconfort_custom_catalog';

// Barcode Component for Preview
const BarcodePreview = ({ code }: { code: string }) => {
  const imgRef = useRef<HTMLImageElement>(null);

  useEffect(() => {
    if (imgRef.current && code) {
      try {
        const canvas = document.createElement('canvas');
        JsBarcode(canvas, code, {
          format: "CODE128",
          width: 1, 
          height: 30,
          displayValue: false,
          margin: 0,
          background: 'transparent',
          lineColor: '#000000'
        });
        imgRef.current.src = canvas.toDataURL();
      } catch(e) { /* ignore */ }
    }
  }, [code]);

  if (!code) return null;
  return <img ref={imgRef} alt="barcode" className="h-2.5 w-auto max-w-full object-contain opacity-80 mix-blend-multiply mt-0.5" />;
}

export default function App() {
  // Initialize state from localStorage or default
  const [data, setData] = useState<ReceiptData>(() => {
    try {
      const savedData = localStorage.getItem(STORAGE_KEY);
      if (savedData) {
        return { ...INITIAL_DATA, ...JSON.parse(savedData) };
      }
    } catch (error) {}
    return INITIAL_DATA;
  });

  const [salespeople, setSalespeople] = useState<string[]>(() => {
    try {
      const savedTeam = localStorage.getItem(TEAM_STORAGE_KEY);
      if (savedTeam) return JSON.parse(savedTeam);
    } catch (error) {}
    return ['ROBSON', 'SARA'];
