                   </tr>
                 </thead>
                 <tbody className="text-sm">
                   {data.products.map((p, i) => (
                     <tr key={i} className="border-b border-gray-100">
                       <td className="py-3 px-3 font-bold">{p.quantity}</td>
                       <td className="py-3 px-3 uppercase text-xs leading-tight">{p.name}</td>
