import React, { useState, useEffect, useRef, useMemo } from 'react';
import { INITIAL_DATA, ReceiptData, PRODUCTS_LIST, PRODUCT_CATALOG, Product, CatalogItem } from './types';
import { generateReceiptPDF, getReceiptBlob } from './services/pdfService';
import { parseReceiptFromText } from './services/geminiService';
import { Input, Select, TextArea } from './components/Input';
import { 
  User, MapPin, Hash, Map, Building2, 
  Phone, Download, CreditCard, Plus, Trash2, Tag, Percent, Search,
  MessageCircle, FileText, Sparkles, Loader2, Barcode,
  Users, UserPlus, ExternalLink, Share2, RotateCcw, AlertTriangle, PackagePlus, List
} from 'lucide-react';
import Fuse from 'fuse.js';
import JsBarcode from 'jsbarcode';

const STORAGE_KEY = 'belconfort_receipt_data';
const TEAM_STORAGE_KEY = 'belconfort_team_list';
const CUSTOM_CATALOG_KEY = 'belconfort_custom_catalog';

// Barcode Component for Preview
const BarcodePreview = ({ code }: { code: string }) => {
  const imgRef = useRef<HTMLImageElement>(null);

  useEffect(() => {
    if (imgRef.current && code) {
      try {
        const canvas = document.createElement('canvas');
        JsBarcode(canvas, code, {
          format: "CODE128",
          width: 1, 
          height: 30,
          displayValue: false,
          margin: 0,
          background: 'transparent',
          lineColor: '#000000'
        });
        imgRef.current.src = canvas.toDataURL();
      } catch(e) { /* ignore */ }
    }
  }, [code]);

  if (!code) return null;
  return <img ref={imgRef} alt="barcode" className="h-2.5 w-auto max-w-full object-contain opacity-80 mix-blend-multiply mt-0.5" />;
}

export default function App() {
  // Initialize state from localStorage or default
  const [data, setData] = useState<ReceiptData>(() => {
    try {
      const savedData = localStorage.getItem(STORAGE_KEY);
      if (savedData) {
        return { ...INITIAL_DATA, ...JSON.parse(savedData) };
      }
    } catch (error) {}
    return INITIAL_DATA;
  });

  const [salespeople, setSalespeople] = useState<string[]>(() => {
    try {
      const savedTeam = localStorage.getItem(TEAM_STORAGE_KEY);
      if (savedTeam) return JSON.parse(savedTeam);
    } catch (error) {}
    return ['ROBSON', 'SARA'];
  });

  const [customCatalog, setCustomCatalog] = useState<CatalogItem[]>(() => {
    try {
      const saved = localStorage.getItem(CUSTOM_CATALOG_KEY);
      if (saved) return JSON.parse(saved);
    } catch (error) {}
    return [];
  });

  // UI State
  const [activeTab, setActiveTab] = useState<'manual' | 'import' | 'team' | 'catalog'>('manual');
  const [importText, setImportText] = useState("");
  const [isImporting, setIsImporting] = useState(false);
  const [importError, setImportError] = useState<{title: string, msg: string} | null>(null);

  // New Product Catalog Form State
  const [catCategory, setCatCategory] = useState("");
  const [catProduct, setCatProduct] = useState("");
  const [catHeight, setCatHeight] = useState("");
  const [catSize, setCatSize] = useState("");
  const [catColor, setCatColor] = useState("");
  const [catPrice, setCatPrice] = useState("");

  // Temporary state for adding a product to cart
  const [selectedProduct, setSelectedProduct] = useState("");
  const [selectedPrice, setSelectedPrice] = useState("");
  const [selectedQuantity, setSelectedQuantity] = useState("1");
  const [searchTerm, setSearchTerm] = useState("");
  const [isSearchOpen, setIsSearchOpen] = useState(false);
  const [discountInput, setDiscountInput] = useState("");

  const searchInputRef = useRef<HTMLInputElement>(null);

  // Merge catalogs and update Fuse logic (REFACTORED)
  const fullCatalog = useMemo(() => {
    const combined = [...PRODUCT_CATALOG, ...customCatalog];
    return combined.sort((a, b) => a.name.localeCompare(b.name));
  }, [customCatalog]);

  const fullProductNames = useMemo(() => fullCatalog.map(p => p.name), [fullCatalog]);

  // Refactored Fuse: Search is now more precise as it can be updated with custom data
  const fuseInstance = useMemo(() => new Fuse(fullProductNames, {
    includeScore: true,
    threshold: 0.35, // More precise
    ignoreLocation: true,
    minMatchCharLength: 2,
  }), [fullProductNames]);

  useEffect(() => {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(data));
  }, [data]);

  useEffect(() => {
    localStorage.setItem(TEAM_STORAGE_KEY, JSON.stringify(salespeople));
  }, [salespeople]);

  useEffect(() => {
    localStorage.setItem(CUSTOM_CATALOG_KEY, JSON.stringify(customCatalog));
  }, [customCatalog]);

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement>) => {
    const { name, value } = e.target;
    setData(prev => ({ ...prev, [name]: value }));
  };

  const handleAddCustomProduct = () => {
    if (!catCategory.trim() || !catProduct.trim() || !catPrice.trim()) {
      alert("Por favor, preencha pelo menos Categoria, Produto e Preço.");
      return;
    }

    const priceValue = parseFloat(catPrice.replace('.', '').replace(',', '.') || "0");
    // Concatenate name for search precision: CATEGORIA NOME ALTURA TAMANHO COR
    const fullName = `${catCategory} ${catProduct} ${catHeight} ${catSize} ${catColor}`
      .replace(/\s+/g, ' ')
      .trim()
      .toUpperCase();

    if (fullProductNames.includes(fullName)) {
      alert("Este produto já existe no catálogo!");
      return;
    }

    const newItem: CatalogItem = { name: fullName, price: priceValue };
    setCustomCatalog(prev => [...prev, newItem]);

    // Reset form
    setCatCategory("");
    setCatProduct("");
    setCatHeight("");
    setCatSize("");
    setCatColor("");
    setCatPrice("");
    alert("Produto salvo com sucesso!");
  };

  const handleRemoveCustomProduct = (name: string) => {
    if (confirm("Deseja remover este produto do seu catálogo?")) {
      setCustomCatalog(prev => prev.filter(p => p.name !== name));
    }
  };

  const filteredProducts = searchTerm
    ? fuseInstance.search(searchTerm).map(result => result.item)
    : fullProductNames;

  const handleSearchSelect = (name: string) => {
    setSelectedProduct(name);
    setSearchTerm(name);
    setIsSearchOpen(false);
    const item = fullCatalog.find(p => p.name === name);
    if (item) setSelectedPrice(item.price.toFixed(2).replace('.', ','));
  };

  const handleAddProduct = () => {
    if (!selectedProduct) return;
    const priceValue = parseFloat(selectedPrice.replace('.', '').replace(',', '.') || "0");
    const quantityValue = parseInt(selectedQuantity) || 1;
    const pseudoCode = Math.floor(100000 + Math.random() * 900000).toString();

    setData(prev => ({
      ...prev,
      products: [...prev.products, {
        code: pseudoCode,
        name: selectedProduct,
        price: priceValue,
        quantity: quantityValue,
        warrantyTime: "",
        warrantyUnit: "MESES"
      }]
    }));

    setSelectedProduct("");
    setSearchTerm("");
    setSelectedPrice("");
    setSelectedQuantity("1");
  };

  const handleSmartImport = async () => {
    if (!importText.trim()) return;
    setIsImporting(true);
    setImportError(null);
    try {
      const result = await parseReceiptFromText(importText, fullProductNames);
      let updatedProducts = [...data.products];
      if (result.items && Array.isArray(result.items)) {
        result.items.forEach((item: { name: string, quantity: number }) => {
            const systemProduct = fullCatalog.find(p => p.name === item.name);
            if (systemProduct) {
                const quantityToAdd = item.quantity || 1;
                const existingIdx = updatedProducts.findIndex(p => p.name === systemProduct.name);
                if (existingIdx >= 0) {
                    updatedProducts[existingIdx].quantity += quantityToAdd;
                } else {
                    updatedProducts.push({
                        code: Math.floor(100000 + Math.random() * 900000).toString(),
                        name: systemProduct.name,
                        price: systemProduct.price,
                        quantity: quantityToAdd,
                        warrantyTime: "",
                        warrantyUnit: "MESES"
                    });
                }
            }
        });
      }
      setData(prev => ({ ...prev, ...result.clientData, products: updatedProducts }));
      setImportText("");
      setActiveTab('manual');
    } catch (error: any) {
      setImportError({ title: "Erro na IA", msg: error.message });
    } finally {
      setIsImporting(false);
    }
  };

  const subtotal = data.products.reduce((acc, curr) => acc + (curr.price * curr.quantity), 0);
  const manualDiscount = data.discountType === 'fixed' ? data.discountValue : subtotal * (data.discountValue / 100);
  const totalValue = Math.max(0, subtotal - manualDiscount);

  return (
