import React, { useState, useEffect, useRef, useMemo } from 'react';
import { INITIAL_DATA, ReceiptData, PRODUCT_CATALOG, Product, CatalogItem } from './types';
import { generateReceiptPDF, getReceiptBlob } from './services/pdfService';
import { parseReceiptFromText } from './services/geminiService';
import { Input, Select, TextArea } from './components/Input';
import { 
  User, MapPin, Hash, Map, Building2, 
  Phone, Download, CreditCard, Plus, Trash2, Tag, Search,
  MessageCircle, FileText, Sparkles, Loader2, Barcode,
  Users, UserPlus, ExternalLink, Share2, RotateCcw, PackagePlus, List, ChevronRight
} from 'lucide-react';
import Fuse from 'fuse.js';
import JsBarcode from 'jsbarcode';

const STORAGE_KEY = 'belconfort_receipt_data';
const TEAM_STORAGE_KEY = 'belconfort_team_list';
const CUSTOM_CATALOG_KEY = 'belconfort_custom_catalog';

// Barcode Component for Preview
const BarcodePreview = ({ code }: { code: string }) => {
  const imgRef = useRef<HTMLImageElement>(null);

  useEffect(() => {
    if (imgRef.current && code) {
      try {
        const canvas = document.createElement('canvas');
        JsBarcode(canvas, code, {
          format: "CODE128",
          width: 1, 
          height: 30,
          displayValue: false,
          margin: 0,
          background: 'transparent',
          lineColor: '#000000'
        });
        imgRef.current.src = canvas.toDataURL();
      } catch(e) { /* ignore */ }
    }
  }, [code]);

  if (!code) return null;
  return <img ref={imgRef} alt="barcode" className="h-2.5 w-auto max-w-full object-contain opacity-80 mix-blend-multiply mt-0.5" />;
}

export default function App() {
  const [data, setData] = useState<ReceiptData>(() => {
    try {
      const savedData = localStorage.getItem(STORAGE_KEY);
      if (savedData) return { ...INITIAL_DATA, ...JSON.parse(savedData) };
    } catch (error) {}
    return INITIAL_DATA;
  });

  const [salespeople, setSalespeople] = useState<string[]>(() => {
    try {
      const savedTeam = localStorage.getItem(TEAM_STORAGE_KEY);
      if (savedTeam) return JSON.parse(savedTeam);
    } catch (error) {}
    return ['ROBSON', 'SARA'];
  });

  const [customCatalog, setCustomCatalog] = useState<CatalogItem[]>(() => {
    try {
      const saved = localStorage.getItem(CUSTOM_CATALOG_KEY);
      if (saved) return JSON.parse(saved);
    } catch (error) {}
    return [];
  });

  // UI Tabs
  const [activeTab, setActiveTab] = useState<'manual' | 'import' | 'team' | 'catalog'>('manual');

  // Catalog Form State
  const [catCategory, setCatCategory] = useState("");
  const [catProduct, setCatProduct] = useState("");
  const [catHeight, setCatHeight] = useState("");
  const [catSize, setCatSize] = useState("");
  const [catColor, setCatColor] = useState("");
  const [catPrice, setCatPrice] = useState("");

  // Search & Sales State
  const [searchTerm, setSearchTerm] = useState("");
  const [isSearchOpen, setIsSearchOpen] = useState(false);
  const [selectedProduct, setSelectedProduct] = useState("");
  const [selectedPrice, setSelectedPrice] = useState("");
  const [selectedQuantity, setSelectedQuantity] = useState("1");
  const [importText, setImportText] = useState("");
  const [isImporting, setIsImporting] = useState(false);
  const [discountInput, setDiscountInput] = useState("");

  // Fuse.js Integration for Multi-Catalog Search
  const fullCatalog = useMemo(() => {
    const combined = [...PRODUCT_CATALOG, ...customCatalog];
    return combined.sort((a, b) => a.name.localeCompare(b.name));
  }, [customCatalog]);

  const fullProductNames = useMemo(() => fullCatalog.map(p => p.name), [fullCatalog]);

  const fuseInstance = useMemo(() => new Fuse(fullProductNames, {
    includeScore: true,
    threshold: 0.35,
    ignoreLocation: true,
    minMatchCharLength: 2,
  }), [fullProductNames]);

  // Persistance
  useEffect(() => { localStorage.setItem(STORAGE_KEY, JSON.stringify(data)); }, [data]);
  useEffect(() => { localStorage.setItem(TEAM_STORAGE_KEY, JSON.stringify(salespeople)); }, [salespeople]);
  useEffect(() => { localStorage.setItem(CUSTOM_CATALOG_KEY, JSON.stringify(customCatalog)); }, [customCatalog]);

  const handleAddCustomProduct = () => {
    if (!catCategory || !catProduct || !catPrice) {
      alert("Preencha ao menos Categoria, Nome do Produto e Preço.");
      return;
    }
    const priceVal = parseFloat(catPrice.replace('.', '').replace(',', '.') || "0");
    const fullName = `${catCategory} ${catProduct} ${catHeight} ${catSize} ${catColor}`.replace(/\s+/g, ' ').trim().toUpperCase();

    if (fullProductNames.includes(fullName)) {
      alert("Este produto já existe!");
      return;
    }

    setCustomCatalog(prev => [...prev, { name: fullName, price: priceVal }]);
    setCatCategory(""); setCatProduct(""); setCatHeight(""); setCatSize(""); setCatColor(""); setCatPrice("");
    alert("Produto adicionado ao catálogo!");
  };

  const handleSearchSelect = (name: string) => {
    setSelectedProduct(name);
    setSearchTerm(name);
    setIsSearchOpen(false);
    const item = fullCatalog.find(p => p.name === name);
    if (item) setSelectedPrice(item.price.toFixed(2).replace('.', ','));
  };

  const handleAddProduct = () => {
    if (!selectedProduct) return;
    const priceValue = parseFloat(selectedPrice.replace('.', '').replace(',', '.') || "0");
    const quantityValue = parseInt(selectedQuantity) || 1;
    const pseudoCode = Math.floor(100000 + Math.random() * 900000).toString();

    setData(prev => ({
      ...prev,
      products: [...prev.products, {
        code: pseudoCode,
        name: selectedProduct,
        price: priceValue,
        quantity: quantityValue,
        warrantyTime: "",
        warrantyUnit: "MESES"
      }]
    }));
    setSelectedProduct(""); setSearchTerm(""); setSelectedPrice(""); setSelectedQuantity("1");
  };

  // --- FIXED COMBO DISCOUNT LOGIC ---
  const getBundleDetails = (products: Product[]) => {
    let totalDiscount = 0;
    let hasBaseDiscount = false;
    let hasPillowDiscount = false;
    const specificPillowName = "TRAVESSEIRO FLOCOS CONFORTO 20CM 60X40 BRANCO";

    const hasAnyOtherProduct = products.some(p => p.name !== specificPillowName);

    // Identify Mattresses (Colchão)
    let casalMattressCount = 0;
    let queenMattressCount = 0;
    let superKingMattressCount = 0;

    products.forEach(p => {
        const name = p.name.toUpperCase();
        // Check for "COLCHÃO" or "COLCHAO" anywhere in the string
        if (name.includes("COLCHÃO") || name.includes("COLCHAO")) {
            if (name.includes("CASAL")) casalMattressCount += p.quantity;
            else if (name.includes("QUEEN")) queenMattressCount += p.quantity;
            else if (name.includes("SUPER KING")) superKingMattressCount += p.quantity;
        }
    });

    products.forEach(p => {
        const name = p.name.toUpperCase();

        // Pillow Rule
        if (name === specificPillowName && hasAnyOtherProduct) {
            totalDiscount += (p.price * p.quantity);
            hasPillowDiscount = true;
        }

        // Base Box Rules (Refactored to be more flexible)
        if (name.includes("BASE")) {
            let targetPrice = 0;
            let applied = false;

            if (name.includes("CASAL") && casalMattressCount > 0) {
                targetPrice = 250.00;
                const qty = Math.min(p.quantity, casalMattressCount);
                if (qty > 0) {
                    totalDiscount += (Math.max(0, p.price - targetPrice) * qty);
                    casalMattressCount -= qty;
                    applied = true;
                }
            } else if (name.includes("QUEEN") && queenMattressCount > 0) {
                targetPrice = 300.00;
                const qty = Math.min(p.quantity, queenMattressCount);
                if (qty > 0) {
                    totalDiscount += (Math.max(0, p.price - targetPrice) * qty);
                    queenMattressCount -= qty;
                    applied = true;
                }
            } else if (name.includes("SUPER KING") && superKingMattressCount > 0) {
                targetPrice = 350.00;
                const qty = Math.min(p.quantity, superKingMattressCount);
                if (qty > 0) {
                    totalDiscount += (Math.max(0, p.price - targetPrice) * qty);
                    superKingMattressCount -= qty;
                    applied = true;
                }
            }
            if (applied) hasBaseDiscount = true;
        }
    });

    let label = "";
    if (hasBaseDiscount && hasPillowDiscount) label = "Desconto Combo + Travesseiro";
    else if (hasBaseDiscount) label = "Desconto Combo (Base+Colchão)";
    else if (hasPillowDiscount) label = "Desconto Travesseiro Brinde";
    else label = "Desconto Promocional";

    return { totalDiscount, label };
  };

  const subtotal = data.products.reduce((acc, curr) => acc + (curr.price * curr.quantity), 0);
  const bundle = getBundleDetails(data.products);
  const manualDiscount = data.discountType === 'fixed' ? data.discountValue : subtotal * (data.discountValue / 100);
  const totalValue = Math.max(0, subtotal - bundle.totalDiscount - manualDiscount);

