                    <span className="w-1.5 h-6 bg-indigo-500 rounded-full"></span>
                    CADASTRAR PRODUTO
                  </h2>
                  <div className="space-y-4">
                    <Input label="Categoria" value={catCategory} onChange={e => setCatCategory(e.target.value)} placeholder="Ex: COLCHÃO" icon={<Tag className="w-4 h-4"/>}/>
                    <Input label="Produto" value={catProduct} onChange={e => setCatProduct(e.target.value)} placeholder="Ex: AIRTECH SPRINGPOCKET" icon={<PackagePlus className="w-4 h-4"/>}/>
                    <div className="grid grid-cols-2 gap-4">
                      <Input label="Altura" value={catHeight} onChange={e => setCatHeight(e.target.value)} placeholder="Ex: 30CM"/>
                      <Input label="Tamanho" value={catSize} onChange={e => setCatSize(e.target.value)} placeholder="Ex: QUEEN"/>
