                        onChange={e => { setSearchTerm(e.target.value); setIsSearchOpen(true); setSelectedProduct(""); }}
                        onFocus={() => setIsSearchOpen(true)}
                        onBlur={() => setTimeout(() => setIsSearchOpen(false), 200)}
                        icon={<Search className="w-4 h-4" />}
                      />
                      {isSearchOpen && (
                        <div className="absolute z-20 w-full mt-1 bg-gray-800 border border-gray-700 rounded-xl shadow-2xl max-h-64 overflow-y-auto custom-scrollbar">
                          {filteredSearchItems.map((p, idx) => (
                            <button key={idx} className="w-full text-left px-4 py-3 text-[11px] text-gray-200 hover:bg-blue-600 hover:text-white uppercase border-b border-gray-700/50 last:border-0 font-bold" onClick={() => handleSearchSelect(p)}>
                              {p}
                            </button>
                          ))}
                        </div>
                      )}
                    </div>
                    <div className="grid grid-cols-2 gap-3">
                        <Input label="Qtd" type="number" value={selectedQuantity} onChange={e => setSelectedQuantity(e.target.value)}/>
                        <Input label="Preço" value={selectedPrice} readOnly className="bg-gray-800/50 text-gray-500 border-dashed"/>
                    </div>
                    <button onClick={handleAddProduct} className="w-full bg-blue-600 hover:bg-blue-700 text-white font-bold py-4 rounded-xl flex items-center justify-center gap-2 transition-all">
                        <Plus className="w-5 h-5" /> INCLUIR NO CARRINHO
                    </button>
                  </div>
                </div>

                <div className="bg-gray-900 border border-gray-800 rounded-2xl p-6 shadow-xl">
                  <h2 className="text-lg font-bold text-white flex items-center gap-2 mb-6">
                    <span className="w-1.5 h-6 bg-blue-500 rounded-full"></span>
                    DADOS DO CLIENTE
                  </h2>
                  <div className="space-y-4">
                    <div className="grid grid-cols-2 gap-4">
                      <Select label="Vendedor" name="salesperson" value={data.salesperson} onChange={e => setData({...data, salesperson: e.target.value})} options={salespeople} icon={<User className="w-4 h-4"/>}/>
                      <Input label="Pedido" name="saleCode" value={data.saleCode} onChange={e => setData({...data, saleCode: e.target.value})} icon={<Barcode className="w-4 h-4"/>}/>
                    </div>
                    <Input label="Cliente" name="name" value={data.name} onChange={e => setData({...data, name: e.target.value})} icon={<User className="w-4 h-4"/>}/>
                    <div className="grid grid-cols-2 gap-4">
                      <Input label="Rua" name="street" value={data.street} onChange={e => setData({...data, street: e.target.value})}/>
                      <Input label="Nº" name="number" value={data.number} onChange={e => setData({...data, number: e.target.value})}/>
                    </div>
                    <div className="grid grid-cols-3 gap-4">
                      <Input label="Bairro" name="neighborhood" value={data.neighborhood} onChange={e => setData({...data, neighborhood: e.target.value})}/>
                      <Input label="Cidade" name="city" value={data.city} onChange={e => setData({...data, city: e.target.value})}/>
                      <Input label="CPF/CNPJ" name="cpf" value={data.cpf} onChange={e => setData({...data, cpf: e.target.value})}/>
                    </div>
                    <div className="grid grid-cols-2 gap-4">
                      <Input label="Contatos" name="contact1" value={data.contact1} onChange={e => setData({...data, contact1: e.target.value})}/>
                      <Input label="E-mail" name="email" value={data.email} onChange={e => setData({...data, email: e.target.value})}/>
                    </div>
                    <Select label="Pagamento" name="paymentMethod" value={data.paymentMethod} onChange={e => setData({...data, paymentMethod: e.target.value})} options={["DINHEIRO", "PIX", "CARTÃO", "LINK"]}/>
                  </div>
                </div>
              </div>
            )}

            {activeTab === 'team' && (
              <div className="bg-gray-900 border border-gray-800 rounded-2xl p-6 shadow-xl animate-in fade-in duration-500">
                <h2 className="text-lg font-bold text-white flex items-center gap-2 mb-6">
                  <span className="w-1.5 h-6 bg-yellow-500 rounded-full"></span>
                  EQUIPE
                </h2>
                <div className="space-y-4">
                  <div className="flex gap-2 items-end">
                    <Input label="Nome" value={searchTerm} onChange={e => setSearchTerm(e.target.value)} placeholder="NOME DO VENDEDOR"/>
                    <button onClick={() => { if(searchTerm){ setSalespeople([...salespeople, searchTerm.toUpperCase()]); setSearchTerm(""); }}} className="bg-blue-600 p-4 rounded-xl"><Plus className="w-5 h-5"/></button>
                  </div>
                  <div className="space-y-2">
                    {salespeople.map(s => (
                      <div key={s} className="bg-gray-850 p-4 rounded-xl flex justify-between items-center border border-gray-800">
                        <span className="text-sm font-black text-gray-200">{s}</span>
                        <button onClick={() => setSalespeople(salespeople.filter(v => v !== s))} className="text-red-400 p-2"><Trash2 className="w-4 h-4"/></button>
                      </div>
                    ))}
                  </div>
                </div>
              </div>
            )}
          </div>

          {/* PREVIEW SECTION - NOW EXACTLY AS PDF */}
          <div className="lg:col-span-7 space-y-6">
            <div className="bg-gray-900 border border-gray-800 rounded-2xl p-4 flex gap-3 flex-wrap shadow-xl">
              <button onClick={() => generateReceiptPDF({...data, bundleDiscount: bundle.totalDiscount, bundleLabel: bundle.label})} className="flex-1 min-w-[140px] flex items-center justify-center gap-2 bg-blue-600 hover:bg-blue-700 text-white font-bold py-4 rounded-xl transition-all shadow-lg shadow-blue-900/30">
                <Download className="w-5 h-5"/> GERAR PDF
              </button>
              <button onClick={() => { if(confirm("Limpar pedido?")) setData(INITIAL_DATA); }} className="px-6 flex items-center justify-center gap-2 bg-red-600/10 hover:bg-red-600/20 text-red-500 font-bold py-4 rounded-xl border border-red-500/20 transition-all">
                <RotateCcw className="w-5 h-5"/>
              </button>
            </div>

            {/* THE PREVIEW CARD */}
            <div className="bg-white shadow-2xl min-h-[1000px] text-gray-900 flex flex-col font-sans overflow-hidden" style={{ width: '210mm', alignSelf: 'center', margin: '0 auto' }}>

               {/* 1. HEADER SECTION (BLUE) */}
               <div style={{ backgroundColor: COLORS.brandBlue, height: '40mm' }} className="w-full flex items-center px-10 relative">
                 <div className="flex flex-col text-white">
                    <h1 className="text-4xl font-serif font-bold leading-none">BelConfort</h1>
                    <p className="text-[10px] tracking-[0.2em] font-normal mt-1">CAMAS E MÓVEIS</p>
                 </div>

                 <div className="ml-auto text-right text-white space-y-1">
                    <p className="text-[11px] font-bold">CNPJ 60.190.028/0001-60</p>
                    <p className="text-[9px] opacity-90">RUA B, 103C, CASTANHEIRA - BELEM/PA</p>
                    <p className="text-[9px] opacity-90">belconfortcamasemoveis@gmail.com</p>
