                        </div>
                      )}
                    </div>
                    <div className="grid grid-cols-2 gap-3">
                        <Input label="Qtd" type="number" value={selectedQuantity} onChange={e => setSelectedQuantity(e.target.value)}/>
                        <Input label="Preço" value={selectedPrice} readOnly className="bg-gray-800/50 text-gray-500 border-dashed"/>
