                    <button onClick={handleAddProduct} className="w-full bg-blue-600 hover:bg-blue-700 text-white font-bold py-4 rounded-xl flex items-center justify-center gap-2 transition-all">
                        <Plus className="w-5 h-5" /> INCLUIR NO CARRINHO
