import React, { useState, useEffect, useRef, useMemo } from 'react';
import { INITIAL_DATA, ReceiptData, PRODUCT_CATALOG, Product, CatalogItem } from './types';
import { generateReceiptPDF, getReceiptBlob } from './services/pdfService';
import { parseReceiptFromText } from './services/geminiService';
import { Input, Select, TextArea } from './components/Input';
import { 
  User, MapPin, Hash, Map, Building2, 
  Phone, Download, CreditCard, Plus, Trash2, Tag, Search,
  MessageCircle, FileText, Sparkles, Loader2, Barcode,
  Users, UserPlus, ExternalLink, Share2, RotateCcw, PackagePlus, List, ChevronRight,
  Instagram
} from 'lucide-react';
import Fuse from 'fuse.js';
import JsBarcode from 'jsbarcode';

const STORAGE_KEY = 'belconfort_receipt_data';
const TEAM_STORAGE_KEY = 'belconfort_team_list';
const CUSTOM_CATALOG_KEY = 'belconfort_custom_catalog';

// Cores idênticas ao PDF
const COLORS = {
  brandBlue: '#1e40af',
  textDark: '#1f2937',
  textGray: '#6b7280',
  borderGray: '#d1d5db',
  bgLight: '#f9fafb',
  stampBlue: '#1e3a8a',
};

// Barcode Component for Preview
const BarcodePreview = ({ code }: { code: string }) => {
  const imgRef = useRef<HTMLImageElement>(null);

  useEffect(() => {
    if (imgRef.current && code) {
      try {
        const canvas = document.createElement('canvas');
        JsBarcode(canvas, code, {
          format: "CODE128",
          width: 1, 
          height: 30,
          displayValue: false,
          margin: 0,
          background: 'transparent',
          lineColor: '#000000'
        });
        imgRef.current.src = canvas.toDataURL();
      } catch(e) { /* ignore */ }
    }
  }, [code]);

  if (!code) return null;
  return <img ref={imgRef} alt="barcode" className="h-4 w-auto max-w-full object-contain opacity-80 mix-blend-multiply mt-1" />;
}

export default function App() {
  const [data, setData] = useState<ReceiptData>(() => {
    try {
      const savedData = localStorage.getItem(STORAGE_KEY);
      if (savedData) return { ...INITIAL_DATA, ...JSON.parse(savedData) };
    } catch (error) {}
    return INITIAL_DATA;
  });

  const [salespeople, setSalespeople] = useState<string[]>(() => {
    try {
      const savedTeam = localStorage.getItem(TEAM_STORAGE_KEY);
      if (savedTeam) return JSON.parse(savedTeam);
    } catch (error) {}
    return ['ROBSON', 'SARA'];
  });

  const [customCatalog, setCustomCatalog] = useState<CatalogItem[]>(() => {
    try {
      const saved = localStorage.getItem(CUSTOM_CATALOG_KEY);
      if (saved) return JSON.parse(saved);
    } catch (error) {}
    return [];
  });

  // UI Tabs
  const [activeTab, setActiveTab] = useState<'manual' | 'import' | 'team' | 'catalog'>('manual');

  // Catalog Form State
  const [catCategory, setCatCategory] = useState("");
  const [catProduct, setCatProduct] = useState("");
  const [catHeight, setCatHeight] = useState("");
  const [catSize, setCatSize] = useState("");
  const [catColor, setCatColor] = useState("");
  const [catPrice, setCatPrice] = useState("");

  // Search & Sales State
  const [searchTerm, setSearchTerm] = useState("");
  const [isSearchOpen, setIsSearchOpen] = useState(false);
  const [selectedProduct, setSelectedProduct] = useState("");
  const [selectedPrice, setSelectedPrice] = useState("");
  const [selectedQuantity, setSelectedQuantity] = useState("1");
  const [importText, setImportText] = useState("");
  const [isImporting, setIsImporting] = useState(false);

  // Fuse.js Integration for Multi-Catalog Search
  const fullCatalog = useMemo(() => {
    const combined = [...PRODUCT_CATALOG, ...customCatalog];
    return combined.sort((a, b) => a.name.localeCompare(b.name));
  }, [customCatalog]);

  const fullProductNames = useMemo(() => fullCatalog.map(p => p.name), [fullCatalog]);

  const fuseInstance = useMemo(() => new Fuse(fullProductNames, {
    includeScore: true,
    threshold: 0.35,
    ignoreLocation: true,
    minMatchCharLength: 2,
  }), [fullProductNames]);

  // Persistance
  useEffect(() => { localStorage.setItem(STORAGE_KEY, JSON.stringify(data)); }, [data]);
  useEffect(() => { localStorage.setItem(TEAM_STORAGE_KEY, JSON.stringify(salespeople)); }, [salespeople]);
  useEffect(() => { localStorage.setItem(CUSTOM_CATALOG_KEY, JSON.stringify(customCatalog)); }, [customCatalog]);

  const handleAddCustomProduct = () => {
    if (!catCategory || !catProduct || !catPrice) {
      alert("Preencha ao menos Categoria, Nome do Produto e Preço.");
      return;
    }
    const priceVal = parseFloat(catPrice.replace('.', '').replace(',', '.') || "0");
    const fullName = `${catCategory} ${catProduct} ${catHeight} ${catSize} ${catColor}`.replace(/\s+/g, ' ').trim().toUpperCase();

    if (fullProductNames.includes(fullName)) {
      alert("Este produto já existe!");
      return;
    }

    setCustomCatalog(prev => [...prev, { name: fullName, price: priceVal }]);
    setCatCategory(""); setCatProduct(""); setCatHeight(""); setCatSize(""); setCatColor(""); setCatPrice("");
    alert("Produto adicionado ao catálogo!");
  };

  const handleSearchSelect = (name: string) => {
    setSelectedProduct(name);
    setSearchTerm(name);
    setIsSearchOpen(false);
    const item = fullCatalog.find(p => p.name === name);
    if (item) setSelectedPrice(item.price.toFixed(2).replace('.', ','));
  };

  const handleAddProduct = () => {
    if (!selectedProduct) return;
    const priceValue = parseFloat(selectedPrice.replace('.', '').replace(',', '.') || "0");
    const quantityValue = parseInt(selectedQuantity) || 1;
    const pseudoCode = Math.floor(100000 + Math.random() * 900000).toString();

    setData(prev => ({
      ...prev,
      products: [...prev.products, {
        code: pseudoCode,
        name: selectedProduct,
        price: priceValue,
        quantity: quantityValue,
        warrantyTime: "",
        warrantyUnit: "MESES"
      }]
    }));
    setSelectedProduct(""); setSearchTerm(""); setSelectedPrice(""); setSelectedQuantity("1");
  };

  const handleSmartImport = async () => {
    if (!importText.trim()) return;
    setIsImporting(true);
    try {
      const result = await parseReceiptFromText(importText, fullProductNames);
      let updatedProducts = [...data.products];
      if (result.items && Array.isArray(result.items)) {
        result.items.forEach((item: { name: string, quantity: number }) => {
            const systemProduct = fullCatalog.find(p => p.name === item.name);
            if (systemProduct) {
                const quantityToAdd = item.quantity || 1;
                updatedProducts.push({
                    code: Math.floor(100000 + Math.random() * 900000).toString(),
                    name: systemProduct.name,
                    price: systemProduct.price,
                    quantity: quantityToAdd,
                    warrantyTime: "",
                    warrantyUnit: "MESES"
                });
            }
        });
      }
      setData(prev => ({ ...prev, ...result.clientData, products: updatedProducts }));
      setImportText("");
      setActiveTab('manual');
    } catch (error: any) {
      alert("Erro na IA: " + error.message);
    } finally {
      setIsImporting(false);
    }
  };

  // --- RESTORED & FULL COMBO DISCOUNT LOGIC ---
  const getBundleDetails = (products: Product[]) => {
    let totalDiscount = 0;
    let hasBaseDiscount = false;
    let hasPillowDiscount = false;
    const specificPillowName = "TRAVESSEIRO FLOCOS CONFORTO 20CM 60X40 BRANCO";

    // Verifica se existe qualquer produto que NÃO seja o travesseiro de brinde
    const hasAnyOtherProduct = products.some(p => p.name.toUpperCase() !== specificPillowName);

    // Identifica quantidades de Colchões por Tamanho
    let solteiroMattressCount = 0;
    let solteiraoMattressCount = 0;
    let casalMattressCount = 0;
    let queenMattressCount = 0;
    let superKingMattressCount = 0;

    products.forEach(p => {
        const name = p.name.toUpperCase();
        if (name.includes("COLCHÃO") || name.includes("COLCHAO")) {
            if (name.includes("SUPER KING")) superKingMattressCount += p.quantity;
            else if (name.includes("QUEEN")) queenMattressCount += p.quantity;
            else if (name.includes("CASAL")) casalMattressCount += p.quantity;
            else if (name.includes("SOLTEIRÃO") || name.includes("SOLTEIRAO")) solteiraoMattressCount += p.quantity;
            else if (name.includes("SOLTEIRO")) solteiroMattressCount += p.quantity;
        }
    });

    products.forEach(p => {
        const name = p.name.toUpperCase();

        // Regra do Travesseiro: Fica grátis se houver outro produto no carrinho
        if (name === specificPillowName && hasAnyOtherProduct) {
            totalDiscount += (p.price * p.quantity);
            hasPillowDiscount = true;
        }

        // Regra do Combo (Base + Colchão): Aplica preço fixo na Base
        if (name.includes("BASE")) {
            let targetPrice = 0;
            let qtyToApply = 0;

            if (name.includes("SUPER KING") && superKingMattressCount > 0) {
                targetPrice = 350.00;
                qtyToApply = Math.min(p.quantity, superKingMattressCount);
                superKingMattressCount -= qtyToApply;
            } else if (name.includes("QUEEN") && queenMattressCount > 0) {
                targetPrice = 300.00;
                qtyToApply = Math.min(p.quantity, queenMattressCount);
                queenMattressCount -= qtyToApply;
            } else if (name.includes("CASAL") && casalMattressCount > 0) {
                targetPrice = 250.00;
                qtyToApply = Math.min(p.quantity, casalMattressCount);
                casalMattressCount -= qtyToApply;
            } else if ((name.includes("SOLTEIRÃO") || name.includes("SOLTEIRAO")) && solteiraoMattressCount > 0) {
                targetPrice = 200.00;
                qtyToApply = Math.min(p.quantity, solteiraoMattressCount);
                solteiraoMattressCount -= qtyToApply;
            } else if (name.includes("SOLTEIRO") && solteiroMattressCount > 0) {
                targetPrice = 150.00;
                qtyToApply = Math.min(p.quantity, solteiroMattressCount);
                solteiroMattressCount -= qtyToApply;
            }

            if (qtyToApply > 0) {
                const discountPerUnit = Math.max(0, p.price - targetPrice);
                totalDiscount += (discountPerUnit * qtyToApply);
                hasBaseDiscount = true;
            }
        }
    });

    let label = "";
    if (hasBaseDiscount && hasPillowDiscount) label = "Combo Colchão/Base + Brinde";
    else if (hasBaseDiscount) label = "Desconto Combo (Base + Colchão)";
    else if (hasPillowDiscount) label = "Brinde Travesseiro Flocos";
    else label = "Desconto Promocional";

    return { totalDiscount, label };
  };

  const subtotal = data.products.reduce((acc, curr) => acc + (curr.price * curr.quantity), 0);
  const bundle = getBundleDetails(data.products);
  const manualDiscount = data.discountType === 'fixed' ? data.discountValue : subtotal * (data.discountValue / 100);
  const totalValue = Math.max(0, subtotal - bundle.totalDiscount - manualDiscount);

  const filteredSearchItems = searchTerm ? fuseInstance.search(searchTerm).map(r => r.item) : fullProductNames;

  return (
    <div className="min-h-screen bg-gray-950 text-gray-100 font-sans pb-20">
      <header className="border-b border-gray-800 bg-[#0047AB] shadow-lg sticky top-0 z-50">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 h-20 flex items-center justify-between">
          <div className="flex flex-col">
            <h1 className="text-3xl font-serif font-bold text-white tracking-tight">BelConfort</h1>
            <p className="text-blue-100 text-[10px] tracking-[0.2em] uppercase font-medium">Camas e Móveis</p>
          </div>
          <span className="text-[10px] font-bold px-2 py-1 bg-white/10 rounded-full text-white border border-white/20">v1.8.6</span>
        </div>
      </header>

      <main className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
        <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">

          <div className="lg:col-span-5 space-y-6">
            <nav className="flex p-1 space-x-1 bg-gray-900 rounded-xl border border-gray-800">
                {[
                  { id: 'manual', icon: FileText, label: 'Venda' },
                  { id: 'catalog', icon: PackagePlus, label: 'Catálogo' },
                  { id: 'import', icon: Sparkles, label: 'Importar' },
                  { id: 'team', icon: Users, label: 'Equipe' }
                ].map(tab => (
                  <button
                    key={tab.id}
                    onClick={() => setActiveTab(tab.id as any)}
                    className={`flex-1 flex items-center justify-center gap-2 py-2.5 text-xs font-bold rounded-lg transition-all ${
                      activeTab === tab.id ? 'bg-blue-600 text-white shadow-lg' : 'text-gray-400 hover:text-gray-200 hover:bg-gray-800'
                    }`}
                  >
                    <tab.icon className="w-4 h-4" />
                    {tab.label.toUpperCase()}
                  </button>
                ))}
            </nav>

            {activeTab === 'catalog' && (
              <div className="space-y-6 animate-in fade-in slide-in-from-bottom-3 duration-500">
                <div className="bg-gray-900 border border-gray-800 rounded-2xl p-6 shadow-xl">
                  <h2 className="text-lg font-bold text-white flex items-center gap-2 mb-6">
                    <span className="w-1.5 h-6 bg-indigo-500 rounded-full"></span>
                    CADASTRAR PRODUTO
                  </h2>
                  <div className="space-y-4">
                    <Input label="Categoria" value={catCategory} onChange={e => setCatCategory(e.target.value)} placeholder="Ex: COLCHÃO" icon={<Tag className="w-4 h-4"/>}/>
                    <Input label="Produto" value={catProduct} onChange={e => setCatProduct(e.target.value)} placeholder="Ex: AIRTECH SPRINGPOCKET" icon={<PackagePlus className="w-4 h-4"/>}/>
                    <div className="grid grid-cols-2 gap-4">
                      <Input label="Altura" value={catHeight} onChange={e => setCatHeight(e.target.value)} placeholder="Ex: 30CM"/>
                      <Input label="Tamanho" value={catSize} onChange={e => setCatSize(e.target.value)} placeholder="Ex: QUEEN"/>
                    </div>
                    <div className="grid grid-cols-2 gap-4">
                      <Input label="Cor" value={catColor} onChange={e => setCatColor(e.target.value)} placeholder="Ex: BEGE"/>
                      <Input label="Preço (R$)" value={catPrice} onChange={e => setCatPrice(e.target.value)} placeholder="0,00" icon={<CreditCard className="w-4 h-4"/>}/>
                    </div>
                    <button onClick={handleAddCustomProduct} className="w-full bg-indigo-600 hover:bg-indigo-700 text-white font-bold py-4 rounded-xl flex items-center justify-center gap-2 transition-all shadow-lg shadow-indigo-900/30">
                      <Plus className="w-5 h-5"/> SALVAR NO CATÁLOGO
                    </button>
                  </div>
                </div>

                <div className="bg-gray-900 border border-gray-800 rounded-2xl p-6 shadow-xl">
                  <h3 className="text-xs font-black text-gray-500 uppercase tracking-widest mb-4 flex items-center gap-2">
                    <List className="w-4 h-4"/> PERSONALIZADOS ({customCatalog.length})
                  </h3>
                  <div className="space-y-2 max-h-[350px] overflow-y-auto pr-2 custom-scrollbar">
                    {customCatalog.map((item, i) => (
                      <div key={i} className="bg-gray-850 p-4 rounded-xl border border-gray-800 flex justify-between items-center group hover:border-indigo-500/50 transition-colors">
                        <div className="flex-1 truncate pr-4">
                          <p className="text-[11px] font-bold text-white uppercase truncate">{item.name}</p>
                          <p className="text-[10px] text-green-400 font-mono mt-1">{item.price.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' })}</p>
                        </div>
                        <button onClick={() => setCustomCatalog(customCatalog.filter(c => c.name !== item.name))} className="p-2 text-gray-600 hover:text-red-400 hover:bg-red-400/10 rounded-lg transition-all">
                          <Trash2 className="w-4 h-4" />
                        </button>
                      </div>
                    ))}
                  </div>
                </div>
