            )}

            {activeTab === 'import' && (
              <div className="bg-gray-900 border border-gray-800 rounded-2xl p-6 shadow-xl animate-in fade-in duration-500">
                <h2 className="text-lg font-bold text-white flex items-center gap-2 mb-6">
                  <span className="w-1.5 h-6 bg-purple-500 rounded-full"></span>
                  IMPORTAÇÃO INTELIGENTE
                </h2>
                <div className="space-y-4">
                   <TextArea label="Cole o texto do pedido aqui..." value={importText} onChange={e => setImportText(e.target.value)} />
                   <button onClick={handleSmartImport} disabled={isImporting} className="w-full bg-purple-600 hover:bg-purple-700 disabled:bg-purple-900/50 text-white font-bold py-4 rounded-xl flex items-center justify-center gap-2 transition-all shadow-lg shadow-purple-900/30">
                    {isImporting ? <Loader2 className="w-5 h-5 animate-spin" /> : <Sparkles className="w-5 h-5"/>}
                    {isImporting ? 'PROCESSANDO...' : 'PROCESSAR COM IA'}
                  </button>
                </div>
              </div>
            )}

            {activeTab === 'manual' && (
              <div className="space-y-6 animate-in fade-in slide-in-from-bottom-3 duration-500">
                <div className="bg-gray-900 border border-gray-800 rounded-2xl p-6 shadow-xl">
                  <h2 className="text-lg font-bold text-white flex items-center gap-2 mb-6">
                    <span className="w-1.5 h-6 bg-green-500 rounded-full"></span>
                    ADICIONAR AO PEDIDO
                  </h2>
                  <div className="space-y-4">
                    <div className="relative">
                      <Input
                        label="Buscar por Nome, Cor ou Tamanho..."
                        value={searchTerm}
                        onChange={e => { setSearchTerm(e.target.value); setIsSearchOpen(true); setSelectedProduct(""); }}
                        onFocus={() => setIsSearchOpen(true)}
                        onBlur={() => setTimeout(() => setIsSearchOpen(false), 200)}
                        icon={<Search className="w-4 h-4" />}
                      />
                      {isSearchOpen && (
                        <div className="absolute z-20 w-full mt-1 bg-gray-800 border border-gray-700 rounded-xl shadow-2xl max-h-64 overflow-y-auto custom-scrollbar">
                          {filteredSearchItems.map((p, idx) => (
                            <button key={idx} className="w-full text-left px-4 py-3 text-[11px] text-gray-200 hover:bg-blue-600 hover:text-white uppercase border-b border-gray-700/50 last:border-0 font-bold" onClick={() => handleSearchSelect(p)}>
