                      </div>
                      <div className="bg-[#0d1117] border-2 border-gray-800 rounded-xl p-3 flex items-center gap-3">
                        <User className="w-4 h-4 text-gray-600" />
                        <select value={data.salesperson} onChange={e => setData({...data, salesperson: e.target.value})} className="bg-transparent w-full outline-none text-sm font-bold uppercase cursor-pointer">
                          <option value="" disabled>VENDEDOR</option>
                          {salespeople.map(s => <option key={s} value={s}>{s}</option>)}
