                   <div className="grid grid-cols-2 gap-4">
                      <div className="bg-[#0d1117] border-2 border-gray-800 rounded-xl p-3 flex items-center gap-3">
                        <Calendar className="w-4 h-4 text-gray-600" />
                        <input type="date" value={data.date} onChange={e => setData({...data, date: e.target.value})} className="bg-transparent w-full outline-none text-sm font-bold uppercase" />
