                   <div className="bg-[#0d1117] border-2 border-gray-800 rounded-xl p-3 flex items-center gap-3">
                      <User className="w-4 h-4 text-gray-600" />
                      <input value={data.name} onChange={e => setData({...data, name: e.target.value})} className="bg-transparent w-full outline-none text-sm font-black uppercase text-blue-400" placeholder="NOME DO CLIENTE" />
                   </div>

                   <div className="bg-[#0d1117] border-2 border-gray-800 rounded-xl p-3 flex items-center gap-3">
                      <MapPin className="w-4 h-4 text-gray-600" />
                      <input value={data.street} onChange={e => setData({...data, street: e.target.value})} className="bg-transparent w-full outline-none text-sm font-bold uppercase" placeholder="RUA" />
                   </div>

                   <div className="grid grid-cols-2 gap-4">
                      <div className="bg-[#0d1117] border-2 border-gray-800 rounded-xl p-3 flex items-center gap-3">
                         <Hash className="w-4 h-4 text-gray-600" />
                         <input value={data.number} onChange={e => setData({...data, number: e.target.value})} className="bg-transparent w-full outline-none text-sm font-bold uppercase" placeholder="NÚMERO" />
                      </div>
                      <div className="bg-[#0d1117] border-2 border-gray-800 rounded-xl p-3 flex items-center gap-3">
                         <Building2 className="w-4 h-4 text-gray-600" />
                         <input value={data.neighborhood} onChange={e => setData({...data, neighborhood: e.target.value})} className="bg-transparent w-full outline-none text-sm font-bold uppercase" placeholder="BAIRRO" />
                      </div>
                   </div>

                   <div className="bg-[#0d1117] border-2 border-gray-800 rounded-xl p-3 flex items-center gap-3">
                      <MapIcon className="w-4 h-4 text-gray-600" />
                      <input value={data.city} onChange={e => setData({...data, city: e.target.value})} className="bg-transparent w-full outline-none text-sm font-bold uppercase" placeholder="CIDADE" />
                   </div>

                   <div className="bg-[#0d1117] border-2 border-gray-800 rounded-xl p-3 flex items-center gap-3">
                      <FileText className="w-4 h-4 text-gray-600" />
                      <input value={data.complement} onChange={e => setData({...data, complement: e.target.value})} className="bg-transparent w-full outline-none text-sm font-bold uppercase" placeholder="COMPLEMENTO" />
