                   <div className="flex gap-2">
                      <button onClick={handleOpenMaps} className="flex-1 bg-blue-600/10 hover:bg-blue-600/20 text-blue-400 font-black py-4 rounded-xl flex items-center justify-center gap-2 border border-blue-600/20 transition-all text-xs uppercase">
                         <MapIcon className="w-4 h-4" /> LOCALIZAÇÃO <div className="bg-blue-600 p-1 rounded ml-1 text-white"><ExternalLink className="w-3 h-3"/></div>
                      </button>
                      <button className="bg-[#0d1117] p-4 rounded-xl border-2 border-gray-800 text-gray-600"><Share2 className="w-5 h-5"/></button>
                   </div>

                   <div className="bg-[#0d1117] border-2 border-gray-800 rounded-xl p-3 flex items-center gap-3">
                      <Mail className="w-4 h-4 text-gray-600" />
                      <input value={data.email} onChange={e => setData({...data, email: e.target.value})} className="bg-transparent w-full outline-none text-sm font-medium uppercase" placeholder="E-MAIL" />
                   </div>

                   <div className="grid grid-cols-2 gap-4">
                      <div className="bg-[#0d1117] border-2 border-gray-800 rounded-xl p-3 flex items-center gap-3">
                         <Phone className="w-4 h-4 text-gray-600" />
                         <input value={data.contact1} onChange={e => setData({...data, contact1: e.target.value})} className="bg-transparent w-full outline-none text-sm font-bold uppercase" placeholder="CONTATO 1" />
                      </div>
                      <div className="bg-[#0d1117] border-2 border-gray-800 rounded-xl p-3 flex items-center gap-3">
                         <Phone className="w-4 h-4 text-gray-600" />
                         <input value={data.contact2} onChange={e => setData({...data, contact2: e.target.value})} className="bg-transparent w-full outline-none text-sm font-bold uppercase" placeholder="CONTATO 2" />
                      </div>
                   </div>
                </div>
              </div>
            </>
          )}

          {activeTab === 'import' && (
            <div className="bg-[#121826] border border-gray-800 rounded-2xl p-6 shadow-xl space-y-4">
               <h2 className="text-sm font-black text-white flex items-center gap-2 uppercase tracking-widest"><Sparkles className="w-5 h-5 text-blue-400"/> Importar Dados</h2>
               <textarea 
                  className="w-full bg-[#0d1117] border-2 border-gray-800 rounded-xl p-4 text-sm font-medium outline-none h-48 resize-none uppercase"
                  placeholder="COLE O TEXTO DO PEDIDO OU FICHA DO CLIENTE AQUI..."
                  value={importText}
                  onChange={e => setImportText(e.target.value)}
               />
               <button 
                  onClick={handleSmartImport} 
                  disabled={isImporting}
                  className="w-full bg-blue-600 hover:bg-blue-700 disabled:opacity-50 text-white font-black py-4 rounded-xl flex items-center justify-center gap-2 transition-all uppercase tracking-widest"
                >
                  {isImporting ? <Loader2 className="w-5 h-5 animate-spin" /> : <Sparkles className="w-5 h-5" />} Processar com IA
               </button>
            </div>
          )}

          {activeTab === 'team' && (
            <div className="bg-[#121826] border border-gray-800 rounded-2xl p-6 shadow-xl space-y-4">
               <h2 className="text-sm font-black text-white flex items-center gap-2 uppercase tracking-widest"><Users className="w-5 h-5 text-blue-400"/> Lista da Equipe</h2>
               <div className="space-y-2">
                 {salespeople.map(s => (
