                      <Users className="w-4 h-4 text-gray-700 group-hover:text-blue-500 transition-colors" />
                   </div>
                 ))}
               </div>
            </div>
          )}
        </div>

        {/* COLUNA DIREITA: AÇÕES RÁPIDAS E PRÉVIA */}
        <div className="lg:col-span-8 space-y-6">

          {/* BARRA DE AÇÕES RÁPIDAS */}
          <div className="bg-[#121826] border border-gray-800 rounded-2xl p-6 shadow-xl">
             <div className="flex items-center gap-2 mb-4 text-gray-400">
               <LayoutGrid className="w-4 h-4" />
               <span className="text-xs font-black uppercase tracking-widest">Ações Rápidas</span>
