             <div className="flex flex-wrap gap-4">
                <button onClick={() => { if(confirm("Limpar formulário?")) setData(INITIAL_DATA); }} className="bg-red-600 hover:bg-red-700 text-white font-black px-6 py-4 rounded-xl flex items-center gap-2 text-xs shadow-lg transition-all uppercase tracking-widest">
                   <RotateCcw className="w-4 h-4" /> Novo Cliente
