                <button onClick={handleWhatsApp} disabled={isGeneratingMessage} className="bg-[#25D366] hover:bg-[#128C7E] text-white font-black px-6 py-4 rounded-xl flex items-center gap-2 text-xs shadow-lg transition-all uppercase tracking-widest">
                   {isGeneratingMessage ? <Loader2 className="w-4 h-4 animate-spin" /> : <MessageCircle className="w-4 h-4" />} WhatsApp
