                <button onClick={handleEmail} className="bg-gray-700 hover:bg-gray-800 text-white font-black px-6 py-4 rounded-xl flex items-center gap-2 text-xs shadow-lg transition-all uppercase tracking-widest">
                   <Mail className="w-4 h-4" /> E-mail
                </button>
                <button onClick={() => generateReceiptPDF({...data, bundleDiscount})} className="bg-blue-600 hover:bg-blue-700 text-white font-black px-8 py-4 rounded-xl flex items-center gap-2 text-xs shadow-lg transition-all ml-auto uppercase tracking-widest">
