            <div className="absolute top-6 right-6 bg-gray-800 px-3 py-1.5 rounded-lg text-[10px] font-black text-gray-300 border border-gray-700 uppercase tracking-widest">Preview</div>

            <div className="bg-white shadow-[0_0_50px_rgba(0,0,0,0.5)] min-h-[900px] text-gray-900 flex flex-col font-sans overflow-hidden scale-[0.85] origin-top md:scale-95 lg:scale-100" style={{ width: '210mm' }}>
               {/* HEADER DO PDF */}
               <div className="bg-blue-800 h-36 flex items-center px-10 text-white justify-between relative">
                  <div className="flex flex-col">
                    <h1 className="text-4xl font-serif font-bold italic leading-none">BelConfort</h1>
