                       <div className="flex-1 p-2 border-r border-gray-300 bg-gray-50/50"><label className="block text-[7px] text-gray-400 font-black uppercase mb-1">DATA DO PEDIDO</label><span className="font-bold">{data.date || '-'}</span></div>
