import React, { useState, useEffect, useRef, useMemo } from 'react';
import { INITIAL_DATA, ReceiptData, PRODUCT_CATALOG, Product, CatalogItem } from './types';
import { generateReceiptPDF } from './services/pdfService';
import { generateClientMessage, parseReceiptFromText } from './services/geminiService';
import { 
  User, MapPin, Hash, Calendar, Building2, 
  Phone, Download, CreditCard, Plus, Trash2, Tag, Search,
  MessageCircle, FileText, Sparkles, Loader2, Barcode,
  Users, UserPlus, ExternalLink, Share2, RotateCcw, PackagePlus, List, ChevronRight,
  Instagram, Mail, Map as MapIcon, Send, Globe, LayoutGrid
} from 'lucide-react';
import Fuse from 'fuse.js';
import JsBarcode from 'jsbarcode';

// Barcode Component for the Preview Area
const BarcodePreview = ({ code }: { code: string }) => {
  const imgRef = useRef<HTMLImageElement>(null);
  useEffect(() => {
    if (imgRef.current && code) {
      try {
        const canvas = document.createElement('canvas');
        JsBarcode(canvas, code, {
          format: "CODE128", width: 1, height: 30, displayValue: false, margin: 0, background: 'transparent', lineColor: '#000000'
        });
        imgRef.current.src = canvas.toDataURL();
      } catch(e) {}
    }
  }, [code]);
  if (!code) return null;
  return <img ref={imgRef} alt="barcode" className="h-4 w-auto max-w-full object-contain opacity-80 mix-blend-multiply mt-1" />;
}

export default function App() {
  const [data, setData] = useState<ReceiptData>(() => {
    const saved = localStorage.getItem('belconfort_receipt_data');
    return saved ? JSON.parse(saved) : INITIAL_DATA;
  });

  const [salespeople] = useState<string[]>(() => {
    const saved = localStorage.getItem('belconfort_team_list');
    return saved ? JSON.parse(saved) : ['ROBSON', 'SARA'];
  });

  const [activeTab, setActiveTab] = useState<'manual' | 'import' | 'team'>('manual');
  const [searchTerm, setSearchTerm] = useState("");
  const [isSearchOpen, setIsSearchOpen] = useState(false);
  const [selectedProduct, setSelectedProduct] = useState("");
  const [selectedPrice, setSelectedPrice] = useState("");
  const [selectedQuantity, setSelectedQuantity] = useState("1");
  const [isGeneratingMessage, setIsGeneratingMessage] = useState(false);
  const [importText, setImportText] = useState("");
  const [isImporting, setIsImporting] = useState(false);

  const fullCatalog = PRODUCT_CATALOG;
  const fullProductNames = useMemo(() => fullCatalog.map(p => p.name), []);
  const fuseInstance = useMemo(() => new Fuse(fullProductNames, { threshold: 0.35 }), [fullProductNames]);

  useEffect(() => { localStorage.setItem('belconfort_receipt_data', JSON.stringify(data)); }, [data]);

  const handleSearchSelect = (name: string) => {
    setSelectedProduct(name);
    setSearchTerm(name);
    setIsSearchOpen(false);
    const item = fullCatalog.find(p => p.name === name);
    if (item) setSelectedPrice(item.price.toFixed(2).replace('.', ','));
  };

  const handleAddProduct = () => {
    if (!selectedProduct) return;
    const priceValue = parseFloat(selectedPrice.replace('.', '').replace(',', '.') || "0");
    const quantityValue = parseInt(selectedQuantity) || 1;
    setData(prev => ({
      ...prev,
      products: [...prev.products, {
        code: Math.floor(100000 + Math.random() * 900000).toString(),
        name: selectedProduct,
        price: priceValue,
        quantity: quantityValue,
        warrantyTime: "12",
        warrantyUnit: "MESES"
      }]
    }));
    setSelectedProduct(""); setSearchTerm(""); setSelectedPrice(""); setSelectedQuantity("1");
  };

  const removeProduct = (index: number) => {
    setData(prev => ({ ...prev, products: prev.products.filter((_, i) => i !== index) }));
  };

  const handleSmartImport = async () => {
    if (!importText.trim()) return;
    setIsImporting(true);
    try {
      const result = await parseReceiptFromText(importText, fullProductNames);
      let updatedProducts = [...data.products];
      if (result.items && Array.isArray(result.items)) {
        result.items.forEach((item: { name: string, quantity: number }) => {
            const systemProduct = fullCatalog.find(p => p.name === item.name);
            if (systemProduct) {
                updatedProducts.push({
                    code: Math.floor(100000 + Math.random() * 900000).toString(),
                    name: systemProduct.name,
                    price: systemProduct.price,
                    quantity: item.quantity || 1,
                    warrantyTime: "12",
                    warrantyUnit: "MESES"
                });
            }
        });
      }
      setData(prev => ({ ...prev, ...result.clientData, products: updatedProducts }));
      setImportText("");
      setActiveTab('manual');
    } catch (error: any) {
      alert("Erro na IA: " + error.message);
    } finally {
      setIsImporting(false);
    }
  };

  // Restored Combo and Pillow Discount Logic
  const getBundleDetails = (products: Product[]) => {
    let totalDiscount = 0;
    let label = "";
    const specificPillowName = "TRAVESSEIRO FLOCOS CONFORTO 20CM 60X40 BRANCO";
    const hasAnyOtherProduct = products.some(p => p.name.toUpperCase() !== specificPillowName);

    let counts = { s: 0, sn: 0, c: 0, q: 0, sk: 0 };
    products.forEach(p => {
      const n = p.name.toUpperCase();
      if (n.includes("COLCHÃO") || n.includes("COLCHAO")) {
        if (n.includes("SUPER KING")) counts.sk += p.quantity;
        else if (n.includes("QUEEN")) counts.q += p.quantity;
        else if (n.includes("CASAL")) counts.c += p.quantity;
        else if (n.includes("SOLTEIRÃO") || n.includes("SOLTEIRAO")) counts.sn += p.quantity;
        else if (n.includes("SOLTEIRO")) counts.s += p.quantity;
      }
    });

    let hasBaseDiscount = false;
    let hasPillowDiscount = false;

    products.forEach(p => {
      const n = p.name.toUpperCase();
      if (n === specificPillowName && hasAnyOtherProduct) {
        totalDiscount += (p.price * p.quantity);
        hasPillowDiscount = true;
      }
      if (n.includes("BASE")) {
        let target = 0, qty = 0;
        if (n.includes("SUPER KING") && counts.sk > 0) { target = 350; qty = Math.min(p.quantity, counts.sk); counts.sk -= qty; }
        else if (n.includes("QUEEN") && counts.q > 0) { target = 300; qty = Math.min(p.quantity, counts.q); counts.q -= qty; }
        else if (n.includes("CASAL") && counts.c > 0) { target = 250; qty = Math.min(p.quantity, counts.c); counts.c -= qty; }
        else if ((n.includes("SOLTEIRÃO") || n.includes("SOLTEIRAO")) && counts.sn > 0) { target = 200; qty = Math.min(p.quantity, counts.sn); counts.sn -= qty; }
        else if (n.includes("SOLTEIRO") && counts.s > 0) { target = 150; qty = Math.min(p.quantity, counts.s); counts.s -= qty; }

        if (qty > 0) {
          totalDiscount += (Math.max(0, p.price - target) * qty);
          hasBaseDiscount = true;
        }
      }
    });

    if (hasBaseDiscount && hasPillowDiscount) label = "Combo Colchão/Base + Brinde";
    else if (hasBaseDiscount) label = "Desconto Combo (Base + Colchão)";
    else if (hasPillowDiscount) label = "Brinde Travesseiro Flocos";
    else label = "Desconto Promocional";

    return { totalDiscount, label };
  };

  const subtotal = data.products.reduce((acc, curr) => acc + (curr.price * curr.quantity), 0);
  const bundle = getBundleDetails(data.products);
  const manualDiscount = data.discountType === 'fixed' ? data.discountValue : subtotal * (data.discountValue / 100);
  const totalValue = Math.max(0, subtotal - bundle.totalDiscount - manualDiscount);

  const filteredSearchItems = searchTerm ? fuseInstance.search(searchTerm).map(r => r.item) : fullProductNames;

  const handleWhatsApp = async () => {
    setIsGeneratingMessage(true);
    const msg = await generateClientMessage(data);
    setIsGeneratingMessage(false);
    const phone = data.contact1.replace(/\D/g, '');
    window.open(`https://wa.me/55${phone}?text=${encodeURIComponent(msg)}`, '_blank');
  };

  const handleEmail = () => {
    const subject = `Comprovante de Compra - BelConfort - ${data.name}`;
    const body = `Olá ${data.name},\n\nSegue o resumo do seu pedido feito na BelConfort.\n\nTotal: ${totalValue.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' })}\n\nAtenciosamente,\nEquipe BelConfort`;
    window.open(`mailto:${data.email}?subject=${encodeURIComponent(subject)}&body=${encodeURIComponent(body)}`);
  };

  const handleOpenMaps = () => {
    const address = `${data.street}, ${data.number}, ${data.neighborhood}, ${data.city}`;
    window.open(`https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(address)}`, '_blank');
  };

  return (
    <div className="min-h-screen bg-gray-950 text-gray-200 font-sans">
      {/* HEADER SUPERIOR */}
      <header className="bg-bel-blue px-6 py-4 flex items-center justify-between border-b border-white/10 shadow-lg">
        <div className="flex items-center gap-4">
           <div className="flex flex-col">
             <h1 className="text-2xl font-serif font-bold text-white italic">BelConfort</h1>
             <p className="text-[8px] tracking-[0.3em] text-blue-200 font-bold uppercase">Camas e Móveis</p>
           </div>
        </div>
        <div className="text-right">
           <p className="text-xs font-medium text-blue-100 opacity-80 uppercase tracking-widest">Ecossistema</p>
           <p className="text-sm font-bold text-white">Vendas & Gestão</p>
        </div>
      </header>

      <main className="p-6 max-w-[1600px] mx-auto grid grid-cols-1 lg:grid-cols-12 gap-6">
        {/* COLUNA ESQUERDA: NAVEGAÇÃO E FORMULÁRIOS */}
        <div className="lg:col-span-4 space-y-6">
          <div className="bg-gray-900/50 p-1 rounded-xl flex border border-gray-800">
             <button onClick={() => setActiveTab('manual')} className={`flex-1 py-2 rounded-lg text-xs font-bold flex items-center justify-center gap-2 transition-all ${activeTab === 'manual' ? 'bg-blue-600 text-white shadow-lg' : 'text-gray-500 hover:text-gray-300'}`}>
               <LayoutGrid className="w-4 h-4" /> Manual
             </button>
             <button onClick={() => setActiveTab('import')} className={`flex-1 py-2 rounded-lg text-xs font-bold flex items-center justify-center gap-2 transition-all ${activeTab === 'import' ? 'bg-blue-600 text-white shadow-lg' : 'text-gray-500 hover:text-gray-300'}`}>
               <Sparkles className="w-4 h-4" /> Importar
             </button>
             <button onClick={() => setActiveTab('team')} className={`flex-1 py-2 rounded-lg text-xs font-bold flex items-center justify-center gap-2 transition-all ${activeTab === 'team' ? 'bg-blue-600 text-white shadow-lg' : 'text-gray-500 hover:text-gray-300'}`}>
               <Users className="w-4 h-4" /> Equipe
             </button>
          </div>

          {activeTab === 'manual' && (
            <>
              <div className="bg-[#121826] border border-gray-800 rounded-2xl shadow-xl overflow-hidden">
                <div className="bg-[#1a2233] px-6 py-4 flex justify-between items-center border-b border-gray-800">
                   <h2 className="text-sm font-black text-white flex items-center gap-2 tracking-wide uppercase">
                     <div className="w-1 h-5 bg-green-400 rounded-full"></div> ADICIONAR PRODUTO
