} from 'lucide-react';
import Fuse from 'fuse.js';
import JsBarcode from 'jsbarcode';

// Barcode Component for the Preview Area
const BarcodePreview = ({ code }: { code: string }) => {
  const imgRef = useRef<HTMLImageElement>(null);
  useEffect(() => {
    if (imgRef.current && code) {
      try {
        const canvas = document.createElement('canvas');
        JsBarcode(canvas, code, {
          format: "CODE128", width: 1, height: 30, displayValue: false, margin: 0, background: 'transparent', lineColor: '#000000'
        });
        imgRef.current.src = canvas.toDataURL();
      } catch(e) {}
    }
  }, [code]);
  if (!code) return null;
  return <img ref={imgRef} alt="barcode" className="h-4 w-auto max-w-full object-contain opacity-80 mix-blend-multiply mt-1" />;
};

export default function App() {
  const [data, setData] = useState<ReceiptData>(() => {
    const saved = localStorage.getItem('belconfort_receipt_data');
    return saved ? JSON.parse(saved) : INITIAL_DATA;
  });

  const [salespeople] = useState<string[]>(() => {
    const saved = localStorage.getItem('belconfort_team_list');
    return saved ? JSON.parse(saved) : ['ROBSON', 'SARA'];
  });

  const [activeTab, setActiveTab] = useState<'manual' | 'import' | 'team'>('manual');
  const [searchTerm, setSearchTerm] = useState("");
  const [isSearchOpen, setIsSearchOpen] = useState(false);
  const [selectedProduct, setSelectedProduct] = useState("");
  const [selectedPrice, setSelectedPrice] = useState("");
  const [selectedQuantity, setSelectedQuantity] = useState("1");
  const [isGeneratingMessage, setIsGeneratingMessage] = useState(false);
  const [importText, setImportText] = useState("");
  const [isImporting, setIsImporting] = useState(false);

  const fullCatalog = PRODUCT_CATALOG;
  const fullProductNames = useMemo(() => fullCatalog.map(p => p.name), []);
  const fuseInstance = useMemo(() => new Fuse(fullProductNames, { threshold: 0.35 }), [fullProductNames]);

  useEffect(() => { localStorage.setItem('belconfort_receipt_data', JSON.stringify(data)); }, [data]);

  const handleSearchSelect = (name: string) => {
    setSelectedProduct(name);
    setSearchTerm(name);
    setIsSearchOpen(false);
    const item = fullCatalog.find(p => p.name === name);
    if (item) setSelectedPrice(item.price.toFixed(2).replace('.', ','));
  };

  const handleAddProduct = () => {
    if (!selectedProduct) return;
    const priceValue = parseFloat(selectedPrice.replace('.', '').replace(',', '.') || "0");
    const quantityValue = parseInt(selectedQuantity) || 1;
    setData(prev => ({
      ...prev,
      products: [...prev.products, {
        code: Math.floor(100000 + Math.random() * 900000).toString(),
        name: selectedProduct,
        price: priceValue,
        quantity: quantityValue,
        warrantyTime: "12",
        warrantyUnit: "MESES"
      }]
    }));
    setSelectedProduct(""); setSearchTerm(""); setSelectedPrice(""); setSelectedQuantity("1");
  };

  const removeProduct = (index: number) => {
    setData(prev => ({ ...prev, products: prev.products.filter((_, i) => i !== index) }));
  };

  const handleSmartImport = async () => {
    if (!importText.trim()) return;
    setIsImporting(true);
    try {
      const result = await parseReceiptFromText(importText, fullProductNames);
      let updatedProducts = [...data.products];
      if (result.items && Array.isArray(result.items)) {
        result.items.forEach((item: { name: string, quantity: number }) => {
            const systemProduct = fullCatalog.find(p => p.name === item.name);
            if (systemProduct) {
                updatedProducts.push({
                    code: Math.floor(100000 + Math.random() * 900000).toString(),
                    name: systemProduct.name,
                    price: systemProduct.price,
                    quantity: item.quantity || 1,
                    warrantyTime: "12",
                    warrantyUnit: "MESES"
                });
            }
        });
      }
      setData(prev => ({ ...prev, ...result.clientData, products: updatedProducts }));
      setImportText("");
      setActiveTab('manual');
    } catch (error: any) {
      alert("Erro na IA: " + error.message);
    } finally {
      setIsImporting(false);
    }
  };

  const getBundleDetails = (products: Product[]) => {
    let totalDiscount = 0;
    let label = "";
    const specificPillowName = "TRAVESSEIRO FLOCOS CONFORTO 20CM 60X40 BRANCO";
    const hasAnyOtherProduct = products.some(p => p.name.toUpperCase() !== specificPillowName);

    let counts = { s: 0, sn: 0, c: 0, q: 0, sk: 0 };
    products.forEach(p => {
      const n = p.name.toUpperCase();
      if (n.includes("COLCHÃO") || n.includes("COLCHAO")) {
        if (n.includes("SUPER KING")) counts.sk += p.quantity;
        else if (n.includes("QUEEN")) counts.q += p.quantity;
        else if (n.includes("CASAL")) counts.c += p.quantity;
        else if (n.includes("SOLTEIRÃO") || n.includes("SOLTEIRAO")) counts.sn += p.quantity;
        else if (n.includes("SOLTEIRO")) counts.s += p.quantity;
      }
    });

    let hasBaseDiscount = false;
    let hasPillowDiscount = false;

    products.forEach(p => {
      const n = p.name.toUpperCase();
      if (n === specificPillowName && hasAnyOtherProduct) {
        totalDiscount += (p.price * p.quantity);
        hasPillowDiscount = true;
      }
      if (n.includes("BASE")) {
        let target = 0, qty = 0;
        if (n.includes("SUPER KING") && counts.sk > 0) { target = 350; qty = Math.min(p.quantity, counts.sk); counts.sk -= qty; }
        else if (n.includes("QUEEN") && counts.q > 0) { target = 300; qty = Math.min(p.quantity, counts.q); counts.q -= qty; }
        else if (n.includes("CASAL") && counts.c > 0) { target = 250; qty = Math.min(p.quantity, counts.c); counts.c -= qty; }
        else if ((n.includes("SOLTEIRÃO") || n.includes("SOLTEIRAO")) && counts.sn > 0) { target = 200; qty = Math.min(p.quantity, counts.sn); counts.sn -= qty; }
        else if (n.includes("SOLTEIRO") && counts.s > 0) { target = 150; qty = Math.min(p.quantity, counts.s); counts.s -= qty; }

        if (qty > 0) {
          totalDiscount += (Math.max(0, p.price - target) * qty);
          hasBaseDiscount = true;
        }
      }
    });

