import { GoogleGenAI, Type } from "@google/genai";
import { ReceiptData } from "../types.ts";

export const generateClientMessage = async (data: ReceiptData): Promise<string> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || "" });
  const subtotal = data.products.reduce((acc, curr) => acc + (curr.price * curr.quantity), 0);
  const productsListText = data.products.length > 0 
    ? data.products.map(p => `- ${p.quantity}x ${p.name}`).join('\n')
    : "Não especificado";

  const prompt = `
    Escreva uma mensagem de WhatsApp para o cliente ${data.name} confirmando seu pedido na BelConfort.
    Produtos:
    ${productsListText}
    Total: ${subtotal.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' })}
    Seja amigável e use emojis.
  `;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-2.5-flash",
      contents: prompt,
    });
    return response.text || "Pedido confirmado!";
  } catch (error: any) {
    return `Olá ${data.name}, seu pedido na BelConfort foi confirmado!`;
  }
};

export const parseReceiptFromText = async (text: string, catalog: string[]): Promise<any> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || "" });
  const response = await ai.models.generateContent({
    model: "gemini-2.5-flash",
    contents: `Analise este texto e retorne um JSON com clientData e items:\n${text}`,
    config: { responseMimeType: "application/json" }
  });
  return JSON.parse(response.text || "{}");
};

import { jsPDF } from 'jspdf';
import { ReceiptData } from '../types.ts';

export const generateReceiptPDF = async (data: ReceiptData) => {
  const doc = new jsPDF();
  doc.setFillColor(30, 64, 175);
  doc.rect(0, 0, 210, 30, 'F');
  doc.setTextColor(255, 255, 255);
  doc.setFontSize(22);
  doc.text("BelConfort", 15, 20);

  doc.setTextColor(31, 41, 55);
  doc.setFontSize(12);
  doc.text("COMPROVANTE DE COMPRA", 105, 45, { align: "center" });

  doc.setFontSize(10);
  doc.text(`Cliente: ${data.name || '-'}`, 15, 60);
  doc.text(`Data: ${data.date || '-'}`, 15, 65);
  doc.text(`Valor Total: ${data.bundleDiscount ? 'Com Desconto' : ''}`, 15, 70);

  doc.save(`COMPROVANTE_${data.name || 'CLIENTE'}.pdf`);
};

export const getReceiptBlob = async (data: ReceiptData): Promise<Blob> => {
  const doc = new jsPDF();
  doc.text("BelConfort", 15, 20);
  return doc.output('blob');
};

