import React, { useState, useEffect, useRef, useMemo } from 'react';
import { INITIAL_DATA, ReceiptData, PRODUCTS_LIST, PRODUCT_CATALOG, Product } from './types.ts';
import { generateReceiptPDF, getReceiptBlob } from './services/pdfService.ts';
import { generateClientMessage, parseReceiptFromText } from './services/geminiService.ts';
import { Input, Select, TextArea } from './components/Input.tsx';
import { 
  Calendar, User, MapPin, Hash, Map, Building2, 
  Phone, Download, Printer, CreditCard, Plus, Trash2, Tag, Percent, Search,
  ShieldCheck, Mail, MessageCircle, FileText, Sparkles, Loader2, Barcode,
  Users, UserPlus, ExternalLink, Share2, Copy, RotateCcw, AlertTriangle, Instagram
} from 'lucide-react';
import Fuse from 'fuse.js';
import JsBarcode from 'jsbarcode';

const STORAGE_KEY = 'belconfort_receipt_data';
const TEAM_STORAGE_KEY = 'belconfort_team_list';

const BarcodePreview = ({ code }: { code: string }) => {
  const imgRef = useRef<HTMLImageElement>(null);

  useEffect(() => {
    if (imgRef.current && code) {
      try {
        const canvas = document.createElement('canvas');
        JsBarcode(canvas, code, {
          format: "CODE128",
          width: 1,
          height: 30,
          displayValue: false,
          margin: 0,
          background: 'transparent',
          lineColor: '#000000'
        });
        imgRef.current.src = canvas.toDataURL();
      } catch(e) { /* ignore */ }
    }
  }, [code]);

  if (!code) return null;
  return <img ref={imgRef} alt="barcode" className="h-2.5 w-auto max-w-full object-contain opacity-80 mix-blend-multiply mt-0.5" />;
}

export default function App() {
  const [data, setData] = useState<ReceiptData>(() => {
    try {
      const savedData = localStorage.getItem(STORAGE_KEY);
      if (savedData) {
        return { ...INITIAL_DATA, ...JSON.parse(savedData) };
      }
    } catch (error) {
      console.error("Failed to load from local storage", error);
    }
    return INITIAL_DATA;
  });

  const [salespeople, setSalespeople] = useState<string[]>(() => {
    try {
      const savedTeam = localStorage.getItem(TEAM_STORAGE_KEY);
      if (savedTeam) {
        return JSON.parse(savedTeam);
      }
    } catch (error) {}
    return ['ROBSON', 'SARA'];
  });

  const [newSalespersonName, setNewSalespersonName] = useState("");
  const [activeTab, setActiveTab] = useState<'manual' | 'import' | 'team'>('manual');
  const [importText, setImportText] = useState("");
  const [isImporting, setIsImporting] = useState(false);
  const [importError, setImportError] = useState<{title: string, msg: string} | null>(null);
  const [selectedProduct, setSelectedProduct] = useState("");
  const [selectedPrice, setSelectedPrice] = useState("");
  const [selectedQuantity, setSelectedQuantity] = useState("1");
  const [searchTerm, setSearchTerm] = useState("");
  const [isSearchOpen, setIsSearchOpen] = useState(false);
  const [discountInput, setDiscountInput] = useState("");

  const fuse = useMemo(() => new Fuse(PRODUCTS_LIST, {
    includeScore: true,
    threshold: 0.4,
    ignoreLocation: true,
  }), []);

  useEffect(() => {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(data));
  }, [data]);

  useEffect(() => {
    localStorage.setItem(TEAM_STORAGE_KEY, JSON.stringify(salespeople));
  }, [salespeople]);

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement>) => {
    const { name, value } = e.target;
    setData(prev => ({ ...prev, [name]: value }));
  };

  const handleResetData = () => {
    if (window.confirm("Tem certeza que deseja iniciar um novo atendimento? Todos os dados atuais serão apagados.")) {
        setData(INITIAL_DATA);
        setSearchTerm("");
        setDiscountInput("");
        setSelectedProduct("");
        setSelectedPrice("");
        setSelectedQuantity("1");
        setImportText("");
        setImportError(null);
        setActiveTab('manual');
        window.scrollTo({ top: 0, behavior: 'smooth' });
    }
  };

  const handleAddSalesperson = () => {
    if (newSalespersonName.trim()) {
      const name = newSalespersonName.trim().toUpperCase();
      if (!salespeople.includes(name)) {
        setSalespeople([...salespeople, name]);
      }
      setNewSalespersonName("");
    }
  };

  const handleRemoveSalesperson = (name: string) => {
    setSalespeople(salespeople.filter(s => s !== name));
  };

  const filteredProducts = searchTerm
    ? fuse.search(searchTerm).map(result => result.item)
    : PRODUCTS_LIST;

  const handleSearchSelect = (name: string) => {
    setSelectedProduct(name);
    setSearchTerm(name);
    setIsSearchOpen(false);
    const product = PRODUCT_CATALOG.find(p => p.name === name);
    if (product) {
        setSelectedPrice(product.price.toFixed(2).replace('.', ','));
    } else {
        setSelectedPrice("");
    }
  };

  const handleAddProduct = () => {
    if (!selectedProduct) return;
    const priceValue = parseFloat(selectedPrice.replace('.', '').replace(',', '.') || "0");
    const quantityValue = parseInt(selectedQuantity) || 1;
    const pseudoCode = Math.floor(100000 + Math.random() * 900000).toString();
    const newProduct: Product = {
      code: pseudoCode,
      name: selectedProduct,
      price: priceValue,
      quantity: quantityValue,
      warrantyTime: "",
      warrantyUnit: "MESES"
    };
    setData(prev => ({
      ...prev,
      products: [...prev.products, newProduct]
    }));
    setSelectedProduct("");
    setSearchTerm("");
    setSelectedPrice("");
    setSelectedQuantity("1");
  };

  const handleRemoveProduct = (index: number) => {
    setData(prev => ({
      ...prev,
      products: prev.products.filter((_, i) => i !== index)
    }));
  };

  const handleUpdateProductWarranty = (index: number, field: 'time' | 'unit', value: string) => {
    setData(prev => {
        const newProducts = prev.products.map((p, i) => {
            if (i === index) {
                if (field === 'time') {
                    return { ...p, warrantyTime: value };
                } else {
                    return { ...p, warrantyUnit: value as 'DIAS' | 'MESES' | 'ANOS' };
                }
            }
            return p;
        });
        return { ...prev, products: newProducts };
    });
  };

  const handleDiscountInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const val = e.target.value;
    setDiscountInput(val);
    const num = parseFloat(val.replace('.', '').replace(',', '.') || "0");
    setData(prev => ({ ...prev, discountValue: num }));
  };

  const handleDiscountTypeChange = (e: React.ChangeEvent<HTMLSelectElement>) => {
    setData(prev => ({ ...prev, discountType: e.target.value as 'fixed' | 'percentage' }));
  };

  const handleSmartImport = async () => {
    if (!importText.trim()) return;
    setIsImporting(true);
    setImportError(null);
    try {
      const result = await parseReceiptFromText(importText, PRODUCTS_LIST);
      let updatedProducts = [...data.products];
      if (result.items && Array.isArray(result.items)) {
        result.items.forEach((item: { name: string, quantity: number }) => {
            const systemProduct = PRODUCT_CATALOG.find(p => p.name === item.name);
            if (systemProduct) {
                const quantityToAdd = item.quantity || 1;
                const existingProductIndex = updatedProducts.findIndex(p => p.name === systemProduct.name);
                if (existingProductIndex >= 0) {
                    const existingProduct = updatedProducts[existingProductIndex];
                    updatedProducts[existingProductIndex] = {
                        ...existingProduct,
                        quantity: existingProduct.quantity + quantityToAdd
                    };
                } else {
                    const pseudoCode = Math.floor(100000 + Math.random() * 900000).toString();
                    updatedProducts.push({
                        code: pseudoCode,
                        name: systemProduct.name,
                        price: systemProduct.price,
                        quantity: quantityToAdd,
                        warrantyTime: "",
                        warrantyUnit: "MESES"
                    });
                }
            }
        });
      }
      setData(prev => ({
        ...prev,
        ...result.clientData,
        products: updatedProducts,
      }));
      setImportText("");
      setActiveTab('manual');
    } catch (error: any) {
      setImportError({ title: "Erro na IA", msg: error.message || "Erro desconhecido" });
    } finally {
      setIsImporting(false);
    }
  };

  const getAddressUrl = () => {
    const { street, number, neighborhood, city } = data;
    if (!street && !city) return '';
    const query = encodeURIComponent(`${street}, ${number} - ${neighborhood}, ${city}`);
    return `https://www.google.com/maps/search/?api=1&query=${query}`;
  };

  const handleOpenMap = () => {
    const url = getAddressUrl();
    if (url) window.open(url, '_blank');
  };

  const handleShareLocation = async () => {
    const url = getAddressUrl();
    if (!url) return;
    if (navigator.share) {
        try {
            await navigator.share({
                title: 'Localização do Cliente - BelConfort',
                text: `Endereço do cliente: ${data.street}, ${data.number} - ${data.neighborhood}`,
                url: url
            });
        } catch (err) {}
    } else {
        await navigator.clipboard.writeText(url);
        alert("Link do mapa copiado!");
    }
  };

  const getBundleDetails = (products: Product[]) => {
    let totalDiscount = 0;
    let hasBaseDiscount = false;
    let hasPillowDiscount = false;
    const specificPillowName = "TRAVESSEIRO FLOCOS CONFORTO 20CM 60X40 BRANCO";
    const hasAnyOtherProduct = products.some(p => p.name !== specificPillowName);
    let counts = { casal: 0, queen: 0, sk: 0 };

    products.forEach(p => {
        const name = p.name.toUpperCase();
        if (name.includes("COLCHÃO") || name.includes("COLCHAO")) {
            if (name.includes("CASAL")) counts.casal += p.quantity;
            else if (name.includes("QUEEN")) counts.queen += p.quantity;
            else if (name.includes("SUPER KING")) counts.sk += p.quantity;
        }
    });

    products.forEach(p => {
        const name = p.name.toUpperCase();
        if (name === specificPillowName && hasAnyOtherProduct) {
            totalDiscount += (p.price * p.quantity);
            hasPillowDiscount = true;
        }
        if (name.startsWith("BASE")) {
            let targetPrice = 0;
            let qty = 0;
            if (name.includes("CASAL") && counts.casal > 0) { targetPrice = 250; qty = Math.min(p.quantity, counts.casal); counts.casal -= qty; }
            else if (name.includes("QUEEN") && counts.queen > 0) { targetPrice = 300; qty = Math.min(p.quantity, counts.queen); counts.queen -= qty; }
            else if (name.includes("SUPER KING") && counts.sk > 0) { targetPrice = 350; qty = Math.min(p.quantity, counts.sk); counts.sk -= qty; }

            if (qty > 0) {
                totalDiscount += (Math.max(0, p.price - targetPrice) * qty);
                hasBaseDiscount = true;
            }
        }
    });

    let label = hasBaseDiscount && hasPillowDiscount ? "Combo + Brinde" : hasBaseDiscount ? "Combo Base+Colchão" : hasPillowDiscount ? "Brinde Travesseiro" : "Desconto Promocional";
    return { totalDiscount, label };
  };

  const subtotal = data.products.reduce((acc, curr) => acc + (curr.price * curr.quantity), 0);
  const bundleDetails = getBundleDetails(data.products);
  const totalDiscountValue = bundleDetails.totalDiscount + (data.discountType === 'fixed' ? data.discountValue : subtotal * (data.discountValue / 100));
  const totalValue = Math.max(0, subtotal - totalDiscountValue);

  const handleGeneratePDF = async () => {
    await generateReceiptPDF({ ...data, bundleDiscount: bundleDetails.totalDiscount, bundleLabel: bundleDetails.label });
  };

  const handleSendEmail = async () => {
    const blob = await getReceiptBlob({ ...data, bundleDiscount: bundleDetails.totalDiscount, bundleLabel: bundleDetails.label });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `COMPROVANTE - ${data.name || 'CLIENTE'}.pdf`;
    link.click();
    window.location.href = `mailto:?subject=Comprovante BelConfort&body=Olá ${data.name}, segue comprovante.`;
  };

  const handleSendWhatsApp = async () => {
    const msg = `Olá ${data.name || 'Cliente'}, aqui está o seu comprovante da BelConfort. Valor: ${totalValue.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' })}`;
    window.open(`https://wa.me/?text=${encodeURIComponent(msg)}`, '_blank');
  };

  return (
    <div className="min-h-screen bg-gray-950 text-gray-100 font-sans pb-20">
      <header className="bg-bel-blue px-6 py-4 flex items-center justify-between border-b border-white/10 shadow-lg">
        <div className="flex flex-col">
           <h1 className="text-2xl font-serif font-bold text-white italic leading-tight">BelConfort</h1>
           <p className="text-[8px] tracking-[0.3em] text-blue-200 font-bold uppercase mt-1">Camas e Móveis</p>
        </div>
        <div className="text-right">
           <p className="text-xs font-medium text-blue-100 opacity-80 uppercase tracking-widest">Ecossistema</p>
           <p className="text-sm font-bold text-white">Vendas & Gestão <span className="text-[10px] opacity-60 ml-1">v1.6.0</span></p>
        </div>
      </header>

      <main className="max-w-7xl mx-auto px-4 py-8 grid grid-cols-1 lg:grid-cols-12 gap-8">
        <div className="lg:col-span-5 space-y-6">
          <div className="flex p-1 bg-gray-900 rounded-xl border border-gray-800">
             {(['manual', 'import', 'team'] as const).map(tab => (
               <button key={tab} onClick={() => setActiveTab(tab)} className={`flex-1 py-2.5 text-xs font-bold rounded-lg transition-all capitalize ${activeTab === tab ? 'bg-blue-600 text-white' : 'text-gray-500 hover:text-gray-300'}`}>
                 {tab}
               </button>
             ))}
          </div>

          {activeTab === 'manual' && (
            <div className="space-y-6">
              <div className="bg-[#121826] border border-gray-800 rounded-2xl p-6 shadow-xl">
                <h2 className="text-sm font-black text-white flex items-center gap-2 uppercase mb-6"><Plus className="w-4 h-4 text-green-400" /> Adicionar Produto</h2>
                <div className="space-y-4">
                  <div className="relative">
                    <Input label="Buscar Produto..." value={searchTerm} onChange={e => { setSearchTerm(e.target.value); setIsSearchOpen(true); }} onFocus={() => setIsSearchOpen(true)} onBlur={() => setTimeout(() => setIsSearchOpen(false), 200)} icon={<Search className="w-4 h-4" />} />
                    {isSearchOpen && searchTerm && (
                      <div className="absolute z-50 w-full mt-1 bg-gray-800 border border-gray-700 rounded-lg max-h-60 overflow-y-auto shadow-2xl">
                        {filteredProducts.map(p => <button key={p} className="w-full text-left px-4 py-3 text-xs text-gray-200 hover:bg-blue-600 font-bold border-b border-gray-700 last:border-0 uppercase" onClick={() => handleSearchSelect(p)}>{p}</button>)}
                      </div>
                    )}
                  </div>
                  <div className="grid grid-cols-2 gap-4">
                    <Input label="Qtd" type="number" value={selectedQuantity} onChange={e => setSelectedQuantity(e.target.value)} />
                    <Input label="Preço" value={selectedPrice} readOnly icon={<Tag className="w-4 h-4" />} />
                  </div>
                  <button onClick={handleAddProduct} className="w-full bg-gray-800 hover:bg-blue-600 text-white font-black py-4 rounded-xl flex items-center justify-center gap-2 transition-all border border-gray-700 uppercase"><Plus className="w-5 h-5" /> Adicionar</button>
                </div>
              </div>

              <div className="bg-[#121826] border border-gray-800 rounded-2xl p-6 shadow-xl">
                 <h2 className="text-sm font-black text-white flex items-center gap-2 uppercase mb-6"><User className="w-4 h-4 text-blue-400" /> Dados do Cliente</h2>
                 <div className="space-y-4">
                    <div className="grid grid-cols-2 gap-4">
                       <Input label="Venda" name="saleCode" value={data.saleCode} onChange={handleChange} />
                       <Select label="Vendedor" name="salesperson" value={data.salesperson} onChange={handleChange} options={salespeople} />
                    </div>
                    <Input label="Nome" name="name" value={data.name} onChange={handleChange} />
                    <Input label="Rua" name="street" value={data.street} onChange={handleChange} />
                    <div className="grid grid-cols-2 gap-4">
                       <Input label="Nº" name="number" value={data.number} onChange={handleChange} />
                       <Input label="Bairro" name="neighborhood" value={data.neighborhood} onChange={handleChange} />
                    </div>
                    <Input label="Cidade" name="city" value={data.city} onChange={handleChange} />
                    <div className="flex gap-2">
                       <button onClick={handleOpenMap} className="flex-1 bg-blue-600/10 hover:bg-blue-600/20 text-blue-400 font-black py-3 rounded-xl border border-blue-600/20 text-xs uppercase">Mapa</button>
                       <button onClick={handleShareLocation} className="bg-gray-800 p-3 rounded-xl border border-gray-700"><Share2 className="w-4 h-4"/></button>
                    </div>
                 </div>
              </div>
            </div>
          )}

          {activeTab === 'import' && (
            <div className="bg-[#121826] border border-gray-800 rounded-2xl p-6 shadow-xl">
               <h2 className="text-sm font-black text-white flex items-center gap-2 uppercase mb-4"><Sparkles className="w-4 h-4 text-purple-400" /> Importar</h2>
               <TextArea label="Cole o texto aqui..." value={importText} onChange={e => setImportText(e.target.value)} className="h-40" />
               <button onClick={handleSmartImport} disabled={isImporting} className="w-full bg-purple-600 hover:bg-purple-700 text-white font-black py-4 rounded-xl mt-4 uppercase">IA Processar</button>
            </div>
          )}
        </div>

        <div className="lg:col-span-7 space-y-6">
          <div className="bg-gray-900 border border-gray-800 rounded-2xl p-4 shadow-xl flex flex-wrap gap-3 items-center justify-between">
            <span className="text-xs font-black uppercase text-gray-500 tracking-widest px-2">Ações Rápidas</span>
            <div className="flex gap-3">
              <button onClick={handleResetData} className="bg-red-600 hover:bg-red-700 text-white font-black px-4 py-2 rounded-lg text-xs uppercase">Novo</button>
              <button onClick={handleSendWhatsApp} className="bg-green-600 hover:bg-green-700 text-white font-black px-4 py-2 rounded-lg text-xs uppercase">WhatsApp</button>
              <button onClick={handleGeneratePDF} className="bg-blue-600 hover:bg-blue-700 text-white font-black px-4 py-2 rounded-lg text-xs uppercase">PDF</button>
            </div>
          </div>

          <div className="bg-gray-900 border border-gray-800 rounded-2xl p-8 shadow-2xl flex justify-center overflow-x-auto">
            <div className="bg-white text-gray-900 p-8 rounded shadow-2xl min-h-[900px] w-[210mm] flex flex-col font-sans scale-[0.8] origin-top md:scale-100">
                <div className="bg-blue-800 text-white p-6 -mx-8 -mt-8 mb-6 flex justify-between items-start">
                   <div className="flex flex-col">
                       <h1 className="font-serif font-bold text-3xl italic">BelConfort</h1>
                       <span className="text-[8px] tracking-[0.4em] font-sans font-bold uppercase mt-1">Camas e Móveis</span>
                   </div>
                   <div className="text-right text-[9px] font-medium opacity-80">
                       <p className="font-bold text-[11px] mb-1">CNPJ 60.190.028/0001-60</p>
                       <p>RUA B, 103C, CASTANHEIRA - BELEM/PA</p>
                       <p>(91) 99381-2592</p>
                       <div className="mt-2 flex justify-end"><Instagram className="w-8 h-8 opacity-50" /></div>
                   </div>
                </div>

                <div className="text-center mb-8">
                    <h2 className="text-lg font-black text-gray-800 uppercase tracking-widest">COMPROVANTE DE COMPRA</h2>
                    <p className="text-[10px] text-gray-400 mt-1 font-bold italic">Emissão: {new Date().toLocaleDateString('pt-BR')} às {new Date().toLocaleTimeString('pt-BR', { hour: '2-digit', minute: '2-digit' })}</p>
                </div>

                <div className="border border-gray-300 mb-8 rounded overflow-hidden">
                    <div className="grid grid-cols-[25%_50%_25%] border-b border-gray-300 bg-gray-50/50">
                        <PreviewCell label="DATA" value={data.date || '-'} className="border-r border-gray-300" />
                        <PreviewCell label="CLIENTE" value={data.name} className="border-r border-gray-300" />
                        <PreviewCell label="CPF/CNPJ" value={data.cpf} />
                    </div>
                    <div className="grid grid-cols-[60%_15%_25%] border-b border-gray-300">
                        <PreviewCell label="RUA" value={data.street} className="border-r border-gray-300" />
                        <PreviewCell label="Nº" value={data.number} className="border-r border-gray-300" />
                        <PreviewCell label="CIDADE" value={data.city} />
                    </div>
                    <div className="grid grid-cols-[50%_50%]">
                         <PreviewCell label="E-MAIL" value={data.email} className="border-r border-gray-300" />
                         <PreviewCell label="CONTATOS" value={`${data.contact1} ${data.contact2}`} />
                    </div>
                </div>

                <div className="mb-10 flex-grow">
                    <div className="grid grid-cols-[50px_1fr_40px_70px_70px] bg-gray-100 border-b border-gray-300 text-[8px] font-black text-blue-900 py-2 px-3 uppercase tracking-widest">
                        <span>CÓD</span><span>DESCRIÇÃO</span><span className="text-center">QTD</span><span className="text-right">UNIT</span><span className="text-right">TOTAL</span>
                    </div>
                    {data.products.map((p, i) => (
                        <div key={i} className="grid grid-cols-[50px_1fr_40px_70px_70px] text-[10px] py-3 px-3 border-b border-gray-100 items-center">
                            <div className="flex flex-col items-start">
                                <span className="font-bold">{p.code}</span>
                                <BarcodePreview code={p.code || ''} />
                            </div>
                            <span className="font-bold uppercase text-gray-800">{p.name}</span>
                            <span className="text-center font-black text-blue-900">{p.quantity}</span>
                            <span className="text-right text-gray-500 font-bold">{p.price.toLocaleString('pt-BR')}</span>
                            <span className="text-right font-black text-gray-900">{(p.price * p.quantity).toLocaleString('pt-BR')}</span>
                        </div>
                    ))}
                    {data.products.length === 0 && <div className="py-16 text-center text-gray-300 font-black uppercase text-[12px] italic border-2 border-dashed border-gray-100 mt-4 rounded-xl">- Carrinho Vazio -</div>}
                </div>

                <div className="flex items-start gap-10 mt-auto">
                    <div className="flex-grow border border-gray-300 rounded overflow-hidden text-[9px] uppercase shadow-sm">
                       <div className="flex justify-between p-3 border-b border-gray-300 bg-gray-50/50"><span className="text-gray-400 font-black">VENDA</span><span className="font-black text-blue-900">{data.saleCode || '-'}</span></div>
                       <div className="flex justify-between p-3 border-b border-gray-300"><span className="text-gray-400 font-black">VENDEDOR</span><span className="font-black text-gray-800">{data.salesperson || '-'}</span></div>
                       <div className="flex justify-between p-3"><span className="text-gray-400 font-black">PAGAMENTO</span><span className="font-black text-gray-900">{data.paymentMethod || '-'}</span></div>
                    </div>
                    <div className="w-[90mm] space-y-2">
                         <div className="flex justify-between text-[11px] text-gray-400 font-bold uppercase"><span>Subtotal:</span><span>{subtotal.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' })}</span></div>
                         {bundleDetails.totalDiscount > 0 && <div className="flex justify-between text-[11px] text-blue-600 font-black uppercase"><span>{bundleDetails.label}:</span><span>- {bundleDetails.totalDiscount.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' })}</span></div>}
                         <div className="flex justify-between text-3xl font-black text-blue-900 border-t-4 border-blue-900 pt-3 uppercase tracking-tighter italic"><span>TOTAL:</span><span>{totalValue.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' })}</span></div>
                    </div>
                </div>

                <div className="mt-12 flex flex-col items-center">
