import { GoogleGenAI, Type } from "@google/genai";
import { ReceiptData } from "../types.ts";

export const generateClientMessage = async (data: ReceiptData): Promise<string> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || "" });
  const prompt = `Gere uma mensagem amigável de confirmação de pedido para o cliente ${data.name} da BelConfort.`;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
    });
    return response.text || "Pedido confirmado!";
  } catch (error) {
    return "Pedido confirmado!";
  }
};

export const parseReceiptFromText = async (text: string, catalog: string[]): Promise<any> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || "" });
  const response = await ai.models.generateContent({
    model: "gemini-3-flash-preview",
    contents: `Extraia dados do cliente e produtos deste texto, comparando com o catálogo: ${catalog.join(', ')}. Texto: ${text}`,
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          clientData: {
            type: Type.OBJECT,
            properties: {
              name: { type: Type.STRING },
              street: { type: Type.STRING },
              city: { type: Type.STRING }
            }
          },
          items: {
            type: Type.ARRAY,
            items: {
              type: Type.OBJECT,
              properties: {
                name: { type: Type.STRING },
                quantity: { type: Type.INTEGER }
              }
            }
          }
        }
      }
    }
  });
  return JSON.parse(response.text || "{}");
};

