  const getBundleDetails = (products: Product[]) => {
    let totalDiscount = 0;
    const pillow = "TRAVESSEIRO FLOCOS CONFORTO 20CM 60X40 BRANCO";
    const hasOther = products.some(p => p.name !== pillow);
    products.forEach(p => { if (p.name === pillow && hasOther) totalDiscount += (p.price * p.quantity); });
    return { totalDiscount, label: totalDiscount > 0 ? "Brinde Travesseiro" : "Desconto" };
  };

  const bundle = getBundleDetails(data.products);
  const totalValue = Math.max(0, subtotal - bundle.totalDiscount - (data.discountType === 'fixed' ? data.discountValue : subtotal * (data.discountValue / 100)));

  const handleGeneratePDF = async () => await generateReceiptPDF({...data, bundleDiscount: bundle.totalDiscount, bundleLabel: bundle.label});
  const handleSendWhatsApp = async () => window.open(`https://wa.me/?text=${encodeURIComponent("Confirmando pedido BelConfort...")}`, '_blank');

  return (
    <div className="min-h-screen bg-gray-950 text-gray-100 font-sans pb-20">
      <header className="border-b border-gray-800 bg-[#0047AB] shadow-lg sticky top-0 z-50">
        <div className="max-w-7xl mx-auto px-4 h-20 flex items-center justify-between">
          <div className="flex flex-col">
            <h1 className="text-3xl font-serif font-bold text-white italic">BelConfort</h1>
            <span className="text-[10px] tracking-[0.2em] font-medium text-blue-100 uppercase">Camas e Móveis</span>
          </div>
          <span className="text-[10px] font-medium px-2 py-1 bg-white/10 rounded-full border border-white/20">v1.7.0</span>
        </div>
      </header>

      <main className="max-w-7xl mx-auto px-4 py-8 grid grid-cols-1 lg:grid-cols-12 gap-8">
        <div className="lg:col-span-5 space-y-6">
          <div className="flex p-1 space-x-1 bg-gray-900 rounded-xl border border-gray-800 overflow-x-auto">
                {(['manual', 'import', 'team', 'catalog'] as const).map(tab => (
                    <button key={tab} onClick={() => setActiveTab(tab)} className={`flex-1 flex items-center justify-center gap-2 py-2.5 px-4 text-xs font-bold rounded-lg transition-all capitalize whitespace-nowrap ${activeTab === tab ? 'bg-blue-600 text-white shadow-lg' : 'text-gray-400 hover:text-gray-200'}`}>
                        {tab === 'manual' && <FileText className="w-4 h-4" />}
                        {tab === 'import' && <Sparkles className="w-4 h-4" />}
                        {tab === 'team' && <Users className="w-4 h-4" />}
                        {tab === 'catalog' && <PackageSearch className="w-4 h-4" />}
                        {tab}
                    </button>
                ))}
            </div>

            {activeTab === 'catalog' && (
              <div className="bg-gray-900 border border-gray-800 rounded-2xl p-6 shadow-xl animate-in fade-in slide-in-from-bottom-2">
                  <div className="flex items-center justify-between mb-6">
                    <h2 className="text-lg font-semibold text-white flex items-center gap-2">
                      <span className="w-1 h-6 bg-blue-500 rounded-full"></span>
                      Gerenciar Catálogo
                    </h2>
                  </div>
                  <div className="bg-gray-800/50 p-4 rounded-xl border border-gray-700/50 mb-6 space-y-4">
                    <Input label="Nome do Novo Produto" value={newProductName} onChange={e => setNewProductName(e.target.value)} icon={<PackageSearch className="w-4 h-4"/>} />
                    <Input label="Preço Sugerido (R$)" value={newProductPrice} onChange={e => setNewProductPrice(e.target.value)} icon={<Tag className="w-4 h-4"/>} placeholder="0,00" />
                    <button onClick={handleRegisterProduct} className="w-full bg-blue-600 hover:bg-blue-700 text-white font-bold py-3 rounded-lg flex items-center justify-center gap-2 uppercase text-sm"><Plus className="w-4 h-4" /> Cadastrar Produto</button>
                  </div>
                  <div className="space-y-2">
                    <h3 className="text-[10px] text-gray-500 font-black uppercase tracking-widest mb-2">Produtos Personalizados</h3>
                    {customCatalog.map((p) => (
                      <div key={p.name} className="flex items-center justify-between bg-gray-800 p-3 rounded-lg border border-gray-700">
                         <div className="flex flex-col">
                           <span className="text-sm font-bold text-gray-200 uppercase">{p.name}</span>
                           <span className="text-xs text-green-400 font-bold">{p.price.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' })}</span>
                         </div>
                         <button onClick={() => handleRemoveCustomProduct(p.name)} className="p-2 text-gray-500 hover:text-red-400 transition-colors"><Trash2 className="w-4 h-4" /></button>
                      </div>
                    ))}
                    {customCatalog.length === 0 && <p className="text-center text-gray-500 text-xs py-4 italic">Nenhum produto personalizado cadastrado.</p>}
                  </div>
              </div>
            )}

            {activeTab === 'manual' && (
                <div className="bg-gray-900 border border-gray-800 rounded-2xl p-6 shadow-xl">
                    <h2 className="text-sm font-black text-white flex items-center gap-2 uppercase mb-6"><Plus className="w-4 h-4 text-green-400" /> Carrinho</h2>
                    <div className="space-y-4">
                        <div className="relative">
                            <Input label="Buscar no Catálogo..." value={searchTerm} onChange={e => { setSearchTerm(e.target.value); setIsSearchOpen(true); }} onFocus={() => setIsSearchOpen(true)} onBlur={() => setTimeout(() => setIsSearchOpen(false), 200)} icon={<Search className="w-4 h-4" />} />
                            {isSearchOpen && searchTerm && (
                                <div className="absolute z-50 w-full mt-1 bg-gray-800 border border-gray-700 rounded-lg max-h-60 overflow-y-auto shadow-2xl">
                                    {filteredProducts.map(p => <button key={p} className="w-full text-left px-4 py-3 text-xs text-gray-200 hover:bg-blue-600 font-bold border-b border-gray-700 uppercase" onClick={() => handleSearchSelect(p)}>{p}</button>)}
                                </div>
                            )}
                        </div>
                        <div className="grid grid-cols-2 gap-4">
                            <Input label="Qtd" type="number" value={selectedQuantity} onChange={e => setSelectedQuantity(e.target.value)} />
                            <Input label="Preço" value={selectedPrice} readOnly icon={<Tag className="w-4 h-4" />} />
                        </div>
                        <button onClick={handleAddProduct} className="w-full bg-blue-600 hover:bg-blue-700 text-white font-black py-4 rounded-xl flex items-center justify-center gap-2 uppercase"><Plus className="w-5 h-5" /> Adicionar</button>
                    </div>
                </div>
            )}

            {/* Other tabs components follow the same pattern... */}
        </div>

        <div className="lg:col-span-7 space-y-6">
            {/* Live Preview & Final Summary remain consistent with previous elegant design */}
            <div className="bg-gray-900 border border-gray-800 rounded-2xl p-4 shadow-xl flex flex-wrap gap-3 items-center justify-between">
              <span className="text-xs font-black uppercase text-gray-500 tracking-widest px-2">Painel de Ações</span>
              <div className="flex gap-3">
                <button onClick={handleResetData} className="bg-red-600 hover:bg-red-700 text-white font-bold px-4 py-2 rounded-lg text-xs uppercase">Limpar</button>
                <button onClick={handleSendWhatsApp} className="bg-green-600 hover:bg-green-700 text-white font-bold px-4 py-2 rounded-lg text-xs uppercase">WhatsApp</button>
                <button onClick={handleGeneratePDF} className="bg-blue-600 hover:bg-blue-700 text-white font-bold px-4 py-2 rounded-lg text-xs uppercase">Gerar PDF</button>
              </div>
            </div>

            <div className="bg-white text-gray-900 p-8 rounded shadow-2xl min-h-[900px] flex flex-col scale-[0.9] origin-top md:scale-100">
                {/* Visual Preview content as requested previously */}
                <div className="border-b-2 border-blue-900 pb-4 mb-6 flex justify-between items-center">
                    <div className="font-serif text-2xl font-bold italic text-blue-900">BelConfort</div>
                    <div className="text-right text-[10px] font-bold text-gray-500 uppercase">Comprovante Digital</div>
                </div>
                <div className="flex-grow">
                    {data.products.map((p, i) => (
                        <div key={i} className="flex justify-between py-2 border-b border-gray-100 text-sm">
                            <span className="font-bold uppercase">{p.quantity}x {p.name}</span>
                            <span className="font-black">{(p.price * p.quantity).toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' })}</span>
                        </div>
                    ))}
                    {data.products.length === 0 && <div className="py-20 text-center text-gray-300 uppercase font-black tracking-tighter text-2xl opacity-20">Carrinho Vazio</div>}
                </div>
                <div className="mt-auto pt-6 border-t-4 border-blue-900 flex justify-between items-center">
                    <span className="text-xl font-black uppercase italic text-blue-900">Total Geral:</span>
                    <span className="text-3xl font-black text-blue-900">{totalValue.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' })}</span>
                </div>
            </div>
        </div>
      </main>
    </div>
  );
}

import React, { useState, useEffect, useRef, useMemo } from 'react';
import { INITIAL_DATA, ReceiptData, PRODUCTS_LIST, PRODUCT_CATALOG, Product, CatalogItem } from './types';
import { generateReceiptPDF, getReceiptBlob } from './services/pdfService';
import { generateClientMessage, parseReceiptFromText } from './services/geminiService';
import { Input, Select, TextArea } from './components/Input';
import { 
  Calendar, User, MapPin, Hash, Map, Building2, 
  Phone, Download, Printer, CreditCard, Plus, Trash2, Tag, Percent, Search,
  ShieldCheck, Mail, MessageCircle, FileText, Sparkles, Loader2, Barcode,
  Users, UserPlus, ExternalLink, Share2, Copy, RotateCcw, AlertTriangle,
  PackagePlus, List, ChevronRight, PackageSearch, CheckCircle2
} from 'lucide-react';
import Fuse from 'fuse.js';
import JsBarcode from 'jsbarcode';

const STORAGE_KEY = 'belconfort_receipt_data';
const TEAM_STORAGE_KEY = 'belconfort_team_list';
const CUSTOM_CATALOG_KEY = 'belconfort_custom_catalog';

// Barcode Component for Preview
const BarcodePreview = ({ code }: { code: string }) => {
  const imgRef = useRef<HTMLImageElement>(null);

  useEffect(() => {
    if (imgRef.current && code) {
      try {
        const canvas = document.createElement('canvas');
        JsBarcode(canvas, code, {
          format: "CODE128",
          width: 1, 
          height: 30,
          displayValue: false,
          margin: 0,
          background: 'transparent',
          lineColor: '#000000'
        });
        imgRef.current.src = canvas.toDataURL();
      } catch(e) { /* ignore */ }
    }
  }, [code]);

  if (!code) return null;
  return <img ref={imgRef} alt="barcode" className="h-2.5 w-auto max-w-full object-contain opacity-80 mix-blend-multiply mt-0.5" />;
}

export default function App() {
  // Initialize state from localStorage or default
  const [data, setData] = useState<ReceiptData>(() => {
    try {
      const savedData = localStorage.getItem(STORAGE_KEY);
      if (savedData) return { ...INITIAL_DATA, ...JSON.parse(savedData) };
    } catch (error) { console.error("Failed to load from local storage", error); }
    return INITIAL_DATA;
  });

  const [salespeople, setSalespeople] = useState<string[]>(() => {
    try {
      const savedTeam = localStorage.getItem(TEAM_STORAGE_KEY);
      if (savedTeam) return JSON.parse(savedTeam);
    } catch (error) {}
    return ['ROBSON', 'SARA'];
  });

  // NEW: State for Custom Catalog Items
  const [customCatalog, setCustomCatalog] = useState<CatalogItem[]>(() => {
    try {
      const saved = localStorage.getItem(CUSTOM_CATALOG_KEY);
      if (saved) return JSON.parse(saved);
    } catch (error) {}
    return [];
  });

  const [newProductName, setNewProductName] = useState("");
  const [newProductPrice, setNewProductPrice] = useState("");
  const [newSalespersonName, setNewSalespersonName] = useState("");

  // UI State
  const [activeTab, setActiveTab] = useState<'manual' | 'import' | 'team' | 'catalog'>('manual');
  const [importText, setImportText] = useState("");
  const [isImporting, setIsImporting] = useState(false);
  const [importError, setImportError] = useState<{title: string, msg: string} | null>(null);

  const [selectedProduct, setSelectedProduct] = useState("");
  const [selectedPrice, setSelectedPrice] = useState("");
  const [selectedQuantity, setSelectedQuantity] = useState("1");

  const [searchTerm, setSearchTerm] = useState("");
  const [debouncedSearchTerm, setDebouncedSearchTerm] = useState("");
  const [isSearchOpen, setIsSearchOpen] = useState(false);
  const [discountInput, setDiscountInput] = useState("");

  // Combined Catalog (Static + Custom)
  const fullCatalog = useMemo(() => {
    const combined = [...PRODUCT_CATALOG, ...customCatalog];
    return combined.sort((a, b) => a.name.localeCompare(b.name));
  }, [customCatalog]);

  const fullProductsList = useMemo(() => fullCatalog.map(p => p.name), [fullCatalog]);

  // Re-initialize Fuse instance when catalog changes
  const fuse = useMemo(() => new Fuse(fullProductsList, {
    includeScore: true,
    threshold: 0.4,
    ignoreLocation: true,
  }), [fullProductsList]);

  // Debounce effect for search term
  useEffect(() => {
    if (!searchTerm) { setDebouncedSearchTerm(""); return; }
    const timer = setTimeout(() => setDebouncedSearchTerm(searchTerm), 300);
    return () => clearTimeout(timer);
  }, [searchTerm]);

  // Persistent Effects
  useEffect(() => localStorage.setItem(STORAGE_KEY, JSON.stringify(data)), [data]);
  useEffect(() => localStorage.setItem(TEAM_STORAGE_KEY, JSON.stringify(salespeople)), [salespeople]);
  useEffect(() => localStorage.setItem(CUSTOM_CATALOG_KEY, JSON.stringify(customCatalog)), [customCatalog]);

  const handleRegisterProduct = () => {
    if (newProductName.trim() && newProductPrice.trim()) {
      const priceValue = parseFloat(newProductPrice.replace('.', '').replace(',', '.') || "0");
      const newItem: CatalogItem = {
        name: newProductName.trim().toUpperCase(),
        price: priceValue
      };

      if (fullProductsList.includes(newItem.name)) {
        alert("Já existe um produto com este nome no catálogo.");
        return;
      }

      setCustomCatalog(prev => [...prev, newItem]);
      setNewProductName("");
      setNewProductPrice("");
      alert("Produto adicionado ao sistema!");
    }
  };

  const handleRemoveCustomProduct = (name: string) => {
    if (confirm(`Remover "${name}" do sistema?`)) {
      setCustomCatalog(prev => prev.filter(p => p.name !== name));
    }
  };

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement>) => {
    const { name, value } = e.target;
    setData(prev => ({ ...prev, [name]: value }));
  };

  const handleResetData = () => {
    if (window.confirm("Limpar atendimento atual?")) {
        setData(INITIAL_DATA);
        setSearchTerm("");
        setDiscountInput("");
        setSelectedProduct("");
        setSelectedPrice("");
        setSelectedQuantity("1");
        setImportText("");
        setImportError(null);
        setActiveTab('manual');
        window.scrollTo({ top: 0, behavior: 'smooth' });
    }
  };

  const handleAddSalesperson = () => {
    if (newSalespersonName.trim()) {
      const name = newSalespersonName.trim().toUpperCase();
      if (!salespeople.includes(name)) setSalespeople([...salespeople, name]);
      setNewSalespersonName("");
    }
  };

  const handleRemoveSalesperson = (name: string) => {
    setSalespeople(salespeople.filter(s => s !== name));
  };

  const filteredProducts = debouncedSearchTerm
    ? fuse.search(debouncedSearchTerm).map(result => result.item)
    : fullProductsList;

  const handleSearchSelect = (name: string) => {
    setSelectedProduct(name);
    setSearchTerm(name);
    setDebouncedSearchTerm(name);
    setIsSearchOpen(false);

    const product = fullCatalog.find(p => p.name === name);
    if (product) setSelectedPrice(product.price.toFixed(2).replace('.', ','));
  };

  const handleAddProduct = () => {
    if (!selectedProduct) return;
    const priceValue = parseFloat(selectedPrice.replace('.', '').replace(',', '.') || "0");
    const quantityValue = parseInt(selectedQuantity) || 1;
    const pseudoCode = Math.floor(100000 + Math.random() * 900000).toString();
    setData(prev => ({
      ...prev,
      products: [...prev.products, {
        code: pseudoCode,
        name: selectedProduct,
        price: priceValue,
        quantity: quantityValue,
        warrantyTime: "",
        warrantyUnit: "MESES"
      }]
    }));
    setSelectedProduct("");
    setSearchTerm("");
    setDebouncedSearchTerm("");
    setSelectedPrice("");
    setSelectedQuantity("1");
  };

  const handleRemoveProduct = (index: number) => {
    setData(prev => ({ ...prev, products: prev.products.filter((_, i) => i !== index) }));
  };

  const handleUpdateProductWarranty = (index: number, field: 'time' | 'unit', value: string) => {
    setData(prev => ({
        ...prev,
        products: prev.products.map((p, i) => i === index 
            ? { ...p, [field === 'time' ? 'warrantyTime' : 'warrantyUnit']: value } 
            : p
        )
    }));
  };

  const handleDiscountInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const val = e.target.value;
    setDiscountInput(val);
    const num = parseFloat(val.replace('.', '').replace(',', '.') || "0");
    setData(prev => ({ ...prev, discountValue: num }));
  };

  const handleSmartImport = async () => {
    if (!importText.trim()) return;
    setIsImporting(true);
    setImportError(null);
    try {
      const result = await parseReceiptFromText(importText, fullProductsList);
      let updatedProducts = [...data.products];
      if (result.items && Array.isArray(result.items)) {
        result.items.forEach((item: { name: string, quantity: number }) => {
            const systemProduct = fullCatalog.find(p => p.name === item.name);
            if (systemProduct) {
                const quantityToAdd = item.quantity || 1;
                const existingIdx = updatedProducts.findIndex(p => p.name === systemProduct.name);
                if (existingIdx >= 0) {
                    updatedProducts[existingIdx].quantity += quantityToAdd;
                } else {
                    updatedProducts.push({
                        code: Math.floor(100000 + Math.random() * 900000).toString(),
                        name: systemProduct.name,
                        price: systemProduct.price,
                        quantity: quantityToAdd,
                        warrantyTime: "",
                        warrantyUnit: "MESES"
                    });
                }
            }
        });
      }
      setData(prev => ({ ...prev, ...result.clientData, products: updatedProducts }));
      setImportText("");
      setActiveTab('manual');
    } catch (error: any) {
      setImportError({ title: "Erro na IA", msg: error.message });
    } finally { setIsImporting(false); }
  };

  const getBundleDetails = (products: Product[]) => {
    let totalDiscount = 0;
    let hasBaseDiscount = false;
    let hasPillowDiscount = false;
    const specificPillowName = "TRAVESSEIRO FLOCOS CONFORTO 20CM 60X40 BRANCO";
    const hasAnyOtherProduct = products.some(p => p.name !== specificPillowName);
    let counts = { casal: 0, queen: 0, sk: 0 };

    products.forEach(p => {
        const name = p.name.toUpperCase();
        if (name.includes("COLCHÃO") || name.includes("COLCHAO")) {
            if (name.includes("CASAL")) counts.casal += p.quantity;
            else if (name.includes("QUEEN")) counts.queen += p.quantity;
            else if (name.includes("SUPER KING")) counts.sk += p.quantity;
        }
    });

    products.forEach(p => {
        const name = p.name.toUpperCase();
        if (name === specificPillowName && hasAnyOtherProduct) {
            totalDiscount += (p.price * p.quantity);
            hasPillowDiscount = true;
        }
        if (name.startsWith("BASE")) {
            let targetPrice = 0; let qty = 0;
            if (name.includes("CASAL") && counts.casal > 0) { targetPrice = 250; qty = Math.min(p.quantity, counts.casal); counts.casal -= qty; }
            else if (name.includes("QUEEN") && counts.queen > 0) { targetPrice = 300; qty = Math.min(p.quantity, counts.queen); counts.queen -= qty; }
            else if (name.includes("SUPER KING") && counts.sk > 0) { targetPrice = 350; qty = Math.min(p.quantity, counts.sk); counts.sk -= qty; }
            if (qty > 0) { totalDiscount += (Math.max(0, p.price - targetPrice) * qty); hasBaseDiscount = true; }
        }
    });

    let label = hasBaseDiscount && hasPillowDiscount ? "Desconto Combo + Travesseiro Brinde" : hasBaseDiscount ? "Desconto Combo (Base+Colchão)" : hasPillowDiscount ? "Desconto (Travesseiro Brinde)" : "Desconto Promocional";
    return { totalDiscount, label };
  };

  const subtotal = data.products.reduce((acc, curr) => acc + (curr.price * curr.quantity), 0);
  const bundleDetails = getBundleDetails(data.products);
  const bundleDiscount = bundleDetails.totalDiscount;
  const manualDiscount = data.discountType === 'fixed' ? data.discountValue : subtotal * (data.discountValue / 100);
  const totalValue = Math.max(0, subtotal - bundleDiscount - manualDiscount);

  const handleGeneratePDF = async () => await generateReceiptPDF({...data, bundleDiscount, bundleLabel: bundleDetails.label});

  const handleSendWhatsApp = async () => {
      const msg = await generateClientMessage({...data, bundleDiscount, bundleLabel: bundleDetails.label});
      window.open(`https://wa.me/?text=${encodeURIComponent(msg)}`, '_blank');
  };

  const handleSendEmail = async () => {
      const blob = await getReceiptBlob({...data, bundleDiscount, bundleLabel: bundleDetails.label});
      const url = window.URL.createObjectURL(blob);
      const link = document.createElement('a');
      link.href = url;
      link.download = `COMPROVANTE - ${data.name || 'CLIENTE'}.pdf`;
      link.click();
  };

  return (
    <div className="min-h-screen bg-gray-950 text-gray-100 font-sans selection:bg-blue-500 selection:text-white pb-20">
      <header className="border-b border-gray-800 bg-[#0047AB] shadow-lg sticky top-0 z-50">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 h-20 flex items-center justify-between">
          <div className="flex flex-col">
            <h1 className="text-3xl font-serif font-bold tracking-tight text-white drop-shadow-md">BelConfort</h1>
            <div className="flex items-center gap-3 text-blue-100 text-[10px] tracking-[0.2em] font-medium uppercase mt-[-4px]">
               <span>Camas e Móveis</span>
            </div>
          </div>
          <span className="text-[10px] font-medium px-2 py-1 bg-white/10 rounded-full text-white border border-white/20">v1.7.0</span>
        </div>
      </header>

      <main className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
        <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">
          <div className="lg:col-span-5 space-y-6">
            <div className="flex p-1 space-x-1 bg-gray-900 rounded-xl border border-gray-800 overflow-x-auto">
                {(['manual', 'import', 'team', 'catalog'] as const).map(tab => (
                    <button key={tab} onClick={() => setActiveTab(tab)} className={`flex-1 flex items-center justify-center gap-2 py-2.5 px-4 text-xs font-bold rounded-lg transition-all duration-200 capitalize whitespace-nowrap ${activeTab === tab ? 'bg-blue-600 text-white shadow-lg' : 'text-gray-400 hover:text-gray-200 hover:bg-gray-800'}`}>
                        {tab === 'manual' && <FileText className="w-4 h-4" />}
                        {tab === 'import' && <Sparkles className="w-4 h-4" />}
                        {tab === 'team' && <Users className="w-4 h-4" />}
                        {tab === 'catalog' && <PackageSearch className="w-4 h-4" />}
                        {tab === 'manual' ? 'Carrinho' : tab === 'team' ? 'Equipe' : tab === 'catalog' ? 'Catálogo' : 'Importar'}
                    </button>
                ))}
            </div>

            {activeTab === 'catalog' && (
              <div className="bg-gray-900 border border-gray-800 rounded-2xl p-6 shadow-xl animate-in fade-in slide-in-from-bottom-2 duration-300">
                  <div className="flex items-center justify-between mb-6">
                    <h2 className="text-lg font-semibold text-white flex items-center gap-2">
                      <span className="w-1 h-6 bg-blue-500 rounded-full"></span>
                      Gerenciar Catálogo
                    </h2>
                    <span className="text-xs text-gray-500 uppercase tracking-wider">Novo Produto</span>
                  </div>
                  <div className="bg-gray-800/50 p-4 rounded-xl border border-gray-700/50 mb-6 space-y-4">
