import { Input, Select, TextArea } from './components/Input';
import { 
  Calendar, User, MapPin, Hash, Map, Building2, 
  Phone, Download, Printer, CreditCard, Plus, Trash2, Tag, Percent, Search,
  ShieldCheck, Mail, MessageCircle, FileText, Sparkles, Loader2, Barcode,
  Users, UserPlus, ExternalLink, Share2, Copy, RotateCcw, AlertTriangle,
  PackagePlus, LayoutGrid
} from 'lucide-react';
import Fuse from 'fuse.js';
import JsBarcode from 'jsbarcode';

const STORAGE_KEY = 'belconfort_receipt_data';
const TEAM_STORAGE_KEY = 'belconfort_team_list';
const CUSTOM_CATALOG_KEY = 'belconfort_custom_catalog';

// Barcode Component for Preview
const BarcodePreview = ({ code }: { code: string }) => {
  const imgRef = useRef<HTMLImageElement>(null);

  useEffect(() => {
    if (imgRef.current && code) {
      try {
        const canvas = document.createElement('canvas');
        JsBarcode(canvas, code, {
          format: "CODE128",
          width: 1, 
          height: 30,
          displayValue: false,
          margin: 0,
          background: 'transparent',
          lineColor: '#000000'
        });
        imgRef.current.src = canvas.toDataURL();
      } catch(e) { /* ignore */ }
    }
  }, [code]);

  if (!code) return null;
  return <img ref={imgRef} alt="barcode" className="h-2.5 w-auto max-w-full object-contain opacity-80 mix-blend-multiply mt-0.5" />;
}

export default function App() {
  // Initialize state from localStorage or default
  const [data, setData] = useState<ReceiptData>(() => {
    try {
      const savedData = localStorage.getItem(STORAGE_KEY);
      if (savedData) return { ...INITIAL_DATA, ...JSON.parse(savedData) };
    } catch (error) { console.error("Failed to load data", error); }
    return INITIAL_DATA;
  });

  const [salespeople, setSalespeople] = useState<string[]>(() => {
    try {
      const savedTeam = localStorage.getItem(TEAM_STORAGE_KEY);
      if (savedTeam) return JSON.parse(savedTeam);
    } catch (error) {}
    return ['ROBSON', 'SARA'];
  });

  // NEW: State for Custom Catalog Items
  const [customCatalog, setCustomCatalog] = useState<CatalogItem[]>(() => {
    try {
      const saved = localStorage.getItem(CUSTOM_CATALOG_KEY);
      if (saved) return JSON.parse(saved);
    } catch (error) {}
    return [];
  });

  // NEW: Form state for catalog registration
  const [newCatalogForm, setNewCatalogForm] = useState({
    category: '',
    productName: '',
    height: '',
    size: '',
    color: '',
    price: ''
  });

  const [newSalespersonName, setNewSalespersonName] = useState("");

  // UI State
  const [activeTab, setActiveTab] = useState<'manual' | 'import' | 'team' | 'catalog'>('manual');
  const [importText, setImportText] = useState("");
  const [isImporting, setIsImporting] = useState(false);
  const [importError, setImportError] = useState<{title: string, msg: string} | null>(null);

  const [selectedProduct, setSelectedProduct] = useState("");
  const [selectedPrice, setSelectedPrice] = useState("");
  const [selectedQuantity, setSelectedQuantity] = useState("1");

  const [searchTerm, setSearchTerm] = useState("");
  const [debouncedSearchTerm, setDebouncedSearchTerm] = useState("");
  const [isSearchOpen, setIsSearchOpen] = useState(false);
  const [discountInput, setDiscountInput] = useState("");

  // DYNAMIC CATALOG MERGE
  const fullCatalog = useMemo(() => {
    const combined = [...PRODUCT_CATALOG, ...customCatalog];
    return combined.sort((a, b) => a.name.localeCompare(b.name));
  }, [customCatalog]);

  const fullProductsList = useMemo(() => fullCatalog.map(p => p.name), [fullCatalog]);

  // Re-initialize Fuse instance when catalog changes
  const fuse = useMemo(() => new Fuse(fullProductsList, {
    includeScore: true,
    threshold: 0.4,
    ignoreLocation: true,
  }), [fullProductsList]);

  useEffect(() => {
    if (!searchTerm) { setDebouncedSearchTerm(""); return; }
    const timer = setTimeout(() => setDebouncedSearchTerm(searchTerm), 300);
    return () => clearTimeout(timer);
  }, [searchTerm]);

  useEffect(() => localStorage.setItem(STORAGE_KEY, JSON.stringify(data)), [data]);
  useEffect(() => localStorage.setItem(TEAM_STORAGE_KEY, JSON.stringify(salespeople)), [salespeople]);
  useEffect(() => localStorage.setItem(CUSTOM_CATALOG_KEY, JSON.stringify(customCatalog)), [customCatalog]);

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement>) => {
    const { name, value } = e.target;
    setData(prev => ({ ...prev, [name]: value }));
  };

  const handleResetData = () => {
    if (window.confirm("Tem certeza que deseja iniciar um novo atendimento?")) {
        setData(INITIAL_DATA);
        setSearchTerm("");
        setDiscountInput("");
        setSelectedProduct("");
        setSelectedPrice("");
        setSelectedQuantity("1");
        setImportText("");
        setImportError(null);
        setActiveTab('manual');
        window.scrollTo({ top: 0, behavior: 'smooth' });
    }
  };

  const handleAddSalesperson = () => {
    if (newSalespersonName.trim()) {
      const name = newSalespersonName.trim().toUpperCase();
      if (!salespeople.includes(name)) setSalespeople([...salespeople, name]);
      setNewSalespersonName("");
    }
  };

  const handleRemoveSalesperson = (name: string) => {
    setSalespeople(salespeople.filter(s => s !== name));
  };

  const handleSearchSelect = (name: string) => {
    setSelectedProduct(name);
    setSearchTerm(name);
    setDebouncedSearchTerm(name);
    setIsSearchOpen(false);
    const product = fullCatalog.find(p => p.name === name);
    if (product) setSelectedPrice(product.price.toFixed(2).replace('.', ','));
  };

  const handleAddProduct = () => {
    if (!selectedProduct) return;
    const priceValue = parseFloat(selectedPrice.replace('.', '').replace(',', '.') || "0");
    const quantityValue = parseInt(selectedQuantity) || 1;
    const pseudoCode = Math.floor(100000 + Math.random() * 900000).toString();
    setData(prev => ({
      ...prev,
      products: [...prev.products, {
        code: pseudoCode,
        name: selectedProduct,
        price: priceValue,
        quantity: quantityValue,
        warrantyTime: "",
        warrantyUnit: "MESES"
      }]
    }));
    setSelectedProduct("");
    setSearchTerm("");
    setDebouncedSearchTerm("");
    setSelectedPrice("");
    setSelectedQuantity("1");
  };

  const handleRemoveProduct = (index: number) => {
    setData(prev => ({ ...prev, products: prev.products.filter((_, i) => i !== index) }));
  };

  const handleUpdateProductWarranty = (index: number, field: 'time' | 'unit', value: string) => {
    setData(prev => ({
        ...prev,
        products: prev.products.map((p, i) => i === index 
            ? { ...p, [field === 'time' ? 'warrantyTime' : 'warrantyUnit']: value } 
            : p
        )
    }));
  };

  const handleDiscountInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const val = e.target.value;
    setDiscountInput(val);
    const num = parseFloat(val.replace('.', '').replace(',', '.') || "0");
    setData(prev => ({ ...prev, discountValue: num }));
  };

  const handleSmartImport = async () => {
    if (!importText.trim()) return;
    setIsImporting(true);
    setImportError(null);
    try {
      const result = await parseReceiptFromText(importText, fullProductsList);
      let updatedProducts = [...data.products];
      if (result.items && Array.isArray(result.items)) {
        result.items.forEach((item: { name: string, quantity: number }) => {
            const systemProduct = fullCatalog.find(p => p.name === item.name);
            if (systemProduct) {
                const quantityToAdd = item.quantity || 1;
                const existingIdx = updatedProducts.findIndex(p => p.name === systemProduct.name);
                if (existingIdx >= 0) {
                    updatedProducts[existingIdx].quantity += quantityToAdd;
                } else {
                    updatedProducts.push({
                        code: Math.floor(100000 + Math.random() * 900000).toString(),
                        name: systemProduct.name,
                        price: systemProduct.price,
                        quantity: quantityToAdd,
                        warrantyTime: "",
                        warrantyUnit: "MESES"
                    });
                }
            }
        });
      }
      setData(prev => ({ ...prev, ...result.clientData, products: updatedProducts }));
      setImportText("");
      setActiveTab('manual');
    } catch (error: any) {
      setImportError({ title: "Erro na IA", msg: error.message });
    } finally { setIsImporting(false); }
  };

  // HANDLE CATALOG FORM
  const handleRegisterProduct = (e: React.FormEvent) => {
    e.preventDefault();
    if (!newCatalogForm.productName || !newCatalogForm.price) {
      alert("Produto e Preço são obrigatórios!");
      return;
    }

    const priceValue = parseFloat(newCatalogForm.price.replace('.', '').replace(',', '.') || "0");
    // Format full name based on segments
    const fullName = [
      newCatalogForm.category,
      newCatalogForm.productName,
      newCatalogForm.height,
      newCatalogForm.size,
      newCatalogForm.color
    ].filter(Boolean).join(' ').toUpperCase();

    if (fullProductsList.includes(fullName)) {
      alert("Este produto já existe no catálogo!");
      return;
    }

    const newItem: CatalogItem = { name: fullName, price: priceValue };
    setCustomCatalog(prev => [...prev, newItem]);
    setNewCatalogForm({ category: '', productName: '', height: '', size: '', color: '', price: '' });
    alert("Produto cadastrado com sucesso!");
  };

  const handleRemoveCustomItem = (name: string) => {
    if (confirm(`Remover "${name}" do sistema?`)) {
      setCustomCatalog(prev => prev.filter(p => p.name !== name));
    }
  };

  const getBundleDetails = (products: Product[]) => {
    let totalDiscount = 0;
    const specificPillowName = "TRAVESSEIRO FLOCOS CONFORTO 20CM 60X40 BRANCO";
    const hasAnyOtherProduct = products.some(p => p.name !== specificPillowName);
    products.forEach(p => {
        if (p.name.toUpperCase() === specificPillowName && hasAnyOtherProduct) {
            totalDiscount += (p.price * p.quantity);
        }
    });
    return { totalDiscount, label: "Desconto (Travesseiro Brinde)" };
  };

  const subtotal = data.products.reduce((acc, curr) => acc + (curr.price * curr.quantity), 0);
  const bundle = getBundleDetails(data.products);
  const manualDiscount = data.discountType === 'fixed' ? data.discountValue : subtotal * (data.discountValue / 100);
  const totalValue = Math.max(0, subtotal - bundle.totalDiscount - manualDiscount);

  const handleGeneratePDF = async () => await generateReceiptPDF({...data, bundleDiscount: bundle.totalDiscount, bundleLabel: bundle.label});
  const handleSendWhatsApp = async () => window.open(`https://wa.me/?text=${encodeURIComponent(await generateClientMessage({...data, bundleDiscount: bundle.totalDiscount, bundleLabel: bundle.label}))}`, '_blank');
  const handleSendEmail = async () => {
    const blob = await getReceiptBlob({...data, bundleDiscount: bundle.totalDiscount, bundleLabel: bundle.label});
    const url = window.URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `COMPROVANTE - ${data.name || 'CLIENTE'}.pdf`;
    link.click();
  };

  return (
    <div className="min-h-screen bg-gray-950 text-gray-100 font-sans selection:bg-blue-500 pb-20">
      <header className="border-b border-gray-800 bg-[#0047AB] shadow-lg sticky top-0 z-50">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 h-20 flex items-center justify-between">
          <div className="flex flex-col">
            <h1 className="text-3xl font-serif font-bold tracking-tight text-white drop-shadow-md">BelConfort</h1>
            <div className="flex items-center gap-3 text-blue-100 text-[10px] tracking-[0.2em] font-medium uppercase mt-[-4px]">
               <span>Camas e Móveis</span>
            </div>
          </div>
          <div className="flex items-center gap-4">
             <div className="hidden sm:block text-right">
                <p className="text-xs text-blue-200 font-medium">Ecosistema</p>
                <p className="text-xs text-white font-bold">Vendas & Gestão</p>
             </div>
             <span className="text-[10px] font-medium px-2 py-1 bg-white/10 rounded-full text-white border border-white/20">v1.7.0</span>
          </div>
        </div>
      </header>

      <main className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
