                  <form onSubmit={handleRegisterProduct} className="space-y-4">
                    <div className="grid grid-cols-2 gap-4">
                      <Input label="Categoria" value={newCatalogForm.category} onChange={e => setNewCatalogForm({...newCatalogForm, category: e.target.value})} placeholder="Ex: COLCHÃO" />
