                      <Input label="Tamanho" value={newCatalogForm.size} onChange={e => setNewCatalogForm({...newCatalogForm, size: e.target.value})} placeholder="Ex: CASAL" />
                      <Input label="Cor" value={newCatalogForm.color} onChange={e => setNewCatalogForm({...newCatalogForm, color: e.target.value})} placeholder="Ex: BEGE" />
