                    <Input label="Preço Sugerido (R$)" value={newCatalogForm.price} onChange={e => setNewCatalogForm({...newCatalogForm, price: e.target.value})} icon={<Tag className="w-4 h-4"/>} placeholder="0,00" />
                    <button type="submit" className="w-full bg-blue-600 hover:bg-blue-700 text-white font-bold py-4 rounded-xl flex items-center justify-center gap-2 uppercase tracking-widest transition-all">
