                  <div className="mt-8 space-y-2">
                    <h3 className="text-[10px] text-gray-500 font-black uppercase tracking-widest border-b border-gray-800 pb-2">Produtos Customizados</h3>
                    <div className="max-h-60 overflow-y-auto space-y-1 pr-2 scrollbar-thin scrollbar-thumb-gray-800">
                        {customCatalog.map((p, i) => (
                          <div key={i} className="flex items-center justify-between bg-gray-800/50 p-3 rounded-lg border border-gray-700 hover:border-blue-500/50 transition-colors">
                             <div className="flex flex-col">
                               <span className="text-[10px] font-bold text-gray-200 uppercase">{p.name}</span>
                               <span className="text-[10px] text-green-400 font-bold">{p.price.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' })}</span>
                             </div>
                             <button onClick={() => handleRemoveCustomItem(p.name)} className="p-2 text-gray-500 hover:text-red-400 transition-colors"><Trash2 className="w-4 h-4" /></button>
                          </div>
                        ))}
                        {customCatalog.length === 0 && <p className="text-center text-gray-600 text-xs py-8 italic">Nenhum produto personalizado ainda.</p>}
