            {activeTab === 'manual' && (
              <div className="space-y-6">
                <div className="bg-gray-900 border border-gray-800 rounded-2xl p-6 shadow-xl animate-in fade-in slide-in-from-bottom-2">
                  <h2 className="text-sm font-black text-white flex items-center gap-2 uppercase mb-6"><Plus className="w-4 h-4 text-green-400" /> ADICIONAR PRODUTO</h2>
                  <div className="space-y-4">
                    <div className="relative">
                      <Input label="Buscar no Catálogo..." value={searchTerm} onChange={e => { setSearchTerm(e.target.value); setIsSearchOpen(true); }} onFocus={() => setIsSearchOpen(true)} onBlur={() => setTimeout(() => setIsSearchOpen(false), 200)} icon={<Search className="w-4 h-4" />} />
                      {isSearchOpen && searchTerm && (
                        <div className="absolute z-50 w-full mt-1 bg-gray-800 border border-gray-700 rounded-lg shadow-2xl max-h-60 overflow-y-auto">
                          {(debouncedSearchTerm ? fuse.search(debouncedSearchTerm).map(r => r.item) : fullProductsList).map(p => (
