                    <Select label="Pagamento" name="paymentMethod" value={data.paymentMethod} onChange={handleChange} options={["DINHEIRO", "PIX", "CARTÃO", "OUTROS"]} />
                  </div>
                </div>
              </div>
            )}

            {activeTab === 'import' && (
              <div className="bg-gray-900 border border-gray-800 rounded-2xl p-6 shadow-xl animate-in fade-in slide-in-from-bottom-2 duration-300">
                  <h2 className="text-lg font-semibold text-white flex items-center gap-2 mb-4"><Sparkles className="w-4 h-4 text-purple-400" /> Importar Ficha</h2>
                  <TextArea label="Cole o texto aqui..." value={importText} onChange={e => setImportText(e.target.value)} className="min-h-[200px] mb-4" />
                  <button onClick={handleSmartImport} disabled={isImporting} className="w-full bg-purple-600 hover:bg-purple-700 text-white font-bold py-3 rounded-lg flex items-center justify-center gap-2">
                    {isImporting ? <Loader2 className="w-4 h-4 animate-spin" /> : <Sparkles className="w-4 h-4" />} Processar com IA
                  </button>
              </div>
            )}

            {activeTab === 'team' && (
              <div className="bg-gray-900 border border-gray-800 rounded-2xl p-6 shadow-xl animate-in fade-in slide-in-from-bottom-2">
                  <h2 className="text-lg font-semibold text-white mb-6">Equipe de Vendas</h2>
                  <div className="flex gap-2 mb-6">
                    <Input label="Novo Vendedor" value={newSalespersonName} onChange={e => setNewSalespersonName(e.target.value)} className="uppercase" />
                    <button onClick={handleAddSalesperson} className="bg-blue-600 p-4 rounded-lg"><Plus className="w-5 h-5 text-white" /></button>
                  </div>
                  <div className="space-y-2">
                    {salespeople.map(s => (
                      <div key={s} className="flex items-center justify-between bg-gray-800 p-3 rounded-lg border border-gray-700">
                        <span className="font-bold text-gray-200">{s}</span>
                        <button onClick={() => handleRemoveSalesperson(s)} className="text-gray-500 hover:text-red-400"><Trash2 className="w-4 h-4" /></button>
                      </div>
