    color: '',
    price: ''
  });

  const [newSalespersonName, setNewSalespersonName] = useState("");
  const [activeTab, setActiveTab] = useState<'manual' | 'import' | 'team' | 'catalog'>('manual');
  const [importText, setImportText] = useState("");
  const [isImporting, setIsImporting] = useState(false);
  const [importError, setImportError] = useState<{title: string, msg: string} | null>(null);

  const [selectedProduct, setSelectedProduct] = useState("");
  const [selectedPrice, setSelectedPrice] = useState("");
  const [selectedQuantity, setSelectedQuantity] = useState("1");
  const [searchTerm, setSearchTerm] = useState("");
  const [debouncedSearchTerm, setDebouncedSearchTerm] = useState("");
  const [isSearchOpen, setIsSearchOpen] = useState(false);

  const fullCatalog = useMemo(() => {
    const combined = [...PRODUCT_CATALOG, ...customCatalog];
    return combined.sort((a, b) => a.name.localeCompare(b.name));
  }, [customCatalog]);

  const fullProductsList = useMemo(() => fullCatalog.map(p => p.name), [fullCatalog]);

  const fuse = useMemo(() => new Fuse(fullProductsList, {
    includeScore: true,
    threshold: 0.4,
    ignoreLocation: true,
  }), [fullProductsList]);

  useEffect(() => {
    const timer = setTimeout(() => setDebouncedSearchTerm(searchTerm), 300);
    return () => clearTimeout(timer);
  }, [searchTerm]);

  useEffect(() => localStorage.setItem(STORAGE_KEY, JSON.stringify(data)), [data]);
  useEffect(() => localStorage.setItem(TEAM_STORAGE_KEY, JSON.stringify(salespeople)), [salespeople]);
  useEffect(() => localStorage.setItem(CUSTOM_CATALOG_KEY, JSON.stringify(customCatalog)), [customCatalog]);

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement>) => {
    const { name, value } = e.target;
    setData(prev => ({ ...prev, [name]: value }));
  };

  const handleResetData = () => {
    if (window.confirm("Tem certeza que deseja iniciar um novo atendimento?")) {
        setData(INITIAL_DATA);
        setSearchTerm("");
        setSelectedProduct("");
        setSelectedPrice("");
        setSelectedQuantity("1");
        setImportText("");
        setImportError(null);
        setActiveTab('manual');
        window.scrollTo({ top: 0, behavior: 'smooth' });
    }
  };

  const handleAddSalesperson = () => {
    if (newSalespersonName.trim()) {
      const name = newSalespersonName.trim().toUpperCase();
      if (!salespeople.includes(name)) setSalespeople([...salespeople, name]);
      setNewSalespersonName("");
    }
  };

  const handleRemoveSalesperson = (name: string) => {
    setSalespeople(salespeople.filter(s => s !== name));
  };

  const handleSearchSelect = (name: string) => {
    setSelectedProduct(name);
    setSearchTerm(name);
    setDebouncedSearchTerm(name);
    setIsSearchOpen(false);
    const product = fullCatalog.find(p => p.name === name);
    if (product) setSelectedPrice(product.price.toFixed(2).replace('.', ','));
  };

  const handleAddProduct = () => {
    if (!selectedProduct) return;
    const priceValue = parseFloat(selectedPrice.replace('.', '').replace(',', '.') || "0");
    const quantityValue = parseInt(selectedQuantity) || 1;
    const pseudoCode = Math.floor(100000 + Math.random() * 900000).toString();
    setData(prev => ({
      ...prev,
      products: [...prev.products, {
        code: pseudoCode,
        name: selectedProduct,
        price: priceValue,
        quantity: quantityValue,
        warrantyTime: "",
        warrantyUnit: "MESES"
      }]
    }));
    setSelectedProduct("");
    setSearchTerm("");
    setDebouncedSearchTerm("");
    setSelectedPrice("");
    setSelectedQuantity("1");
  };

  const handleRegisterProduct = (e: React.FormEvent) => {
    e.preventDefault();
    if (!newCatalogForm.productName || !newCatalogForm.price) {
      alert("Produto e Preço são obrigatórios!");
      return;
    }

    const priceValue = parseFloat(newCatalogForm.price.replace('.', '').replace(',', '.') || "0");
    const fullName = [
      newCatalogForm.category,
      newCatalogForm.productName,
      newCatalogForm.height,
      newCatalogForm.size,
      newCatalogForm.color
    ].filter(Boolean).join(' ').toUpperCase();

    if (fullProductsList.includes(fullName)) {
      alert("Este produto já existe no catálogo!");
      return;
    }

    const newItem: CatalogItem = { name: fullName, price: priceValue };
    setCustomCatalog(prev => [...prev, newItem]);
    setNewCatalogForm({ category: '', productName: '', height: '', size: '', color: '', price: '' });
    alert("Produto cadastrado com sucesso!");
  };

  const handleRemoveCustomItem = (name: string) => {
    if (confirm(`Remover "${name}" do sistema?`)) {
      setCustomCatalog(prev => prev.filter(p => p.name !== name));
    }
  };

  const handleSmartImport = async () => {
    if (!importText.trim()) return;
    setIsImporting(true);
    setImportError(null);
    try {
      const result = await parseReceiptFromText(importText, fullProductsList);
      let updatedProducts = [...data.products];
      if (result.items && Array.isArray(result.items)) {
        result.items.forEach((item: { name: string, quantity: number }) => {
            const systemProduct = fullCatalog.find(p => p.name === item.name);
            if (systemProduct) {
                const quantityToAdd = item.quantity || 1;
                const existingIdx = updatedProducts.findIndex(p => p.name === systemProduct.name);
                if (existingIdx >= 0) {
                    updatedProducts[existingIdx].quantity += quantityToAdd;
                } else {
                    updatedProducts.push({
                        code: Math.floor(100000 + Math.random() * 900000).toString(),
                        name: systemProduct.name,
                        price: systemProduct.price,
                        quantity: quantityToAdd,
                        warrantyTime: "",
                        warrantyUnit: "MESES"
                    });
                }
            }
        });
      }
      setData(prev => ({ ...prev, ...result.clientData, products: updatedProducts }));
      setImportText("");
      setActiveTab('manual');
    } catch (error: any) {
      setImportError({ title: "Erro na IA", msg: error.message });
    } finally { setIsImporting(false); }
  };

  const getBundleDetails = (products: Product[]) => {
    let totalDiscount = 0;
    const specificPillowName = "TRAVESSEIRO FLOCOS CONFORTO 20CM 60X40 BRANCO";
    const hasAnyOtherProduct = products.some(p => p.name !== specificPillowName);
    products.forEach(p => {
        if (p.name.toUpperCase() === specificPillowName && hasAnyOtherProduct) {
            totalDiscount += (p.price * p.quantity);
        }
    });
    return { totalDiscount, label: "Desconto (Travesseiro Brinde)" };
  };

  const subtotal = data.products.reduce((acc, curr) => acc + (curr.price * curr.quantity), 0);
  const bundle = getBundleDetails(data.products);
  const manualDiscount = data.discountType === 'fixed' ? data.discountValue : subtotal * (data.discountValue / 100);
  const totalValue = Math.max(0, subtotal - bundle.totalDiscount - manualDiscount);

  const handleGeneratePDF = async () => await generateReceiptPDF({...data, bundleDiscount: bundle.totalDiscount, bundleLabel: bundle.label});
  const handleSendWhatsApp = async () => window.open(`https://wa.me/?text=${encodeURIComponent(await generateClientMessage({...data, bundleDiscount: bundle.totalDiscount, bundleLabel: bundle.label}))}`, '_blank');

  return (
    <div className="min-h-screen bg-gray-950 text-gray-100 font-sans selection:bg-blue-500 pb-20">
      <header className="border-b border-gray-800 bg-[#0047AB] shadow-lg sticky top-0 z-50">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 h-20 flex items-center justify-between">
          <div className="flex flex-col">
            <h1 className="text-3xl font-serif font-bold tracking-tight text-white drop-shadow-md">BelConfort</h1>
            <div className="flex items-center gap-3 text-blue-100 text-[10px] tracking-[0.2em] font-medium uppercase mt-[-4px]">
               <span>Camas e Móveis</span>
            </div>
          </div>
          <div className="flex items-center gap-4">
             <div className="hidden sm:block text-right">
                <p className="text-xs text-blue-200 font-medium">Ecosistema</p>
                <p className="text-xs text-white font-bold">Vendas & Gestão</p>
             </div>
             <span className="text-[10px] font-medium px-2 py-1 bg-white/10 rounded-full text-white border border-white/20">v1.7.0</span>
          </div>
        </div>
      </header>

      <main className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
        <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">
          <div className="lg:col-span-5 space-y-6">
            <div className="flex p-1 space-x-1 bg-gray-900 rounded-xl border border-gray-800 overflow-x-auto">
                {(['manual', 'import', 'catalog', 'team'] as const).map(tab => (
                    <button key={tab} onClick={() => setActiveTab(tab)} className={`flex-1 flex items-center justify-center gap-2 py-2.5 px-4 text-xs font-bold rounded-lg transition-all capitalize whitespace-nowrap ${activeTab === tab ? 'bg-blue-600 text-white shadow-lg' : 'text-gray-400 hover:text-gray-200 hover:bg-gray-800'}`}>
                        {tab === 'manual' && <FileText className="w-4 h-4" />}
                        {tab === 'import' && <Sparkles className="w-4 h-4" />}
                        {tab === 'catalog' && <LayoutGrid className="w-4 h-4" />}
                        {tab === 'team' && <Users className="w-4 h-4" />}
                        {tab === 'manual' ? 'Manual' : tab === 'catalog' ? 'Catálogo' : tab === 'team' ? 'Equipe' : 'Importar'}
                    </button>
                ))}
            </div>

            {activeTab === 'catalog' && (
              <div className="bg-gray-900 border border-gray-800 rounded-2xl p-6 shadow-xl animate-in fade-in slide-in-from-bottom-2 duration-300">
                  <h2 className="text-lg font-semibold text-white flex items-center gap-2 mb-6">
                    <span className="w-1 h-6 bg-blue-500 rounded-full"></span>
                    Gerenciar Catálogo
                  </h2>
                  <form onSubmit={handleRegisterProduct} className="space-y-4">
                    <div className="grid grid-cols-2 gap-4">
                      <Input label="Categoria" value={newCatalogForm.category} onChange={e => setNewCatalogForm({...newCatalogForm, category: e.target.value})} placeholder="Ex: COLCHÃO" />
                      <Input label="Produto" value={newCatalogForm.productName} onChange={e => setNewCatalogForm({...newCatalogForm, productName: e.target.value})} placeholder="Ex: AIRTECH" />
                    </div>
                    <div className="grid grid-cols-3 gap-3">
                      <Input label="Altura" value={newCatalogForm.height} onChange={e => setNewCatalogForm({...newCatalogForm, height: e.target.value})} placeholder="Ex: 25CM" />
                      <Input label="Tamanho" value={newCatalogForm.size} onChange={e => setNewCatalogForm({...newCatalogForm, size: e.target.value})} placeholder="Ex: CASAL" />
                      <Input label="Cor" value={newCatalogForm.color} onChange={e => setNewCatalogForm({...newCatalogForm, color: e.target.value})} placeholder="Ex: BEGE" />
                    </div>
                    <Input label="Preço (R$)" value={newCatalogForm.price} onChange={e => setNewCatalogForm({...newCatalogForm, price: e.target.value})} icon={<Tag className="w-4 h-4"/>} placeholder="0,00" />
                    <button type="submit" className="w-full bg-blue-600 hover:bg-blue-700 text-white font-bold py-4 rounded-xl flex items-center justify-center gap-2 uppercase tracking-widest transition-all">
                      <PackagePlus className="w-5 h-5" /> Cadastrar no Sistema
                    </button>
                  </form>
                  <div className="mt-8 space-y-2">
                    <h3 className="text-[10px] text-gray-500 font-black uppercase tracking-widest border-b border-gray-800 pb-2">Itens Personalizados</h3>
                    <div className="max-h-60 overflow-y-auto space-y-1 pr-2 scrollbar-thin scrollbar-thumb-gray-800">
                        {customCatalog.map((p, i) => (
                          <div key={i} className="flex items-center justify-between bg-gray-800/50 p-3 rounded-lg border border-gray-700">
                             <div className="flex flex-col">
                               <span className="text-[10px] font-bold text-gray-200 uppercase">{p.name}</span>
                               <span className="text-[10px] text-green-400 font-bold">{p.price.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' })}</span>
                             </div>
                             <button onClick={() => handleRemoveCustomItem(p.name)} className="p-2 text-gray-500 hover:text-red-400 transition-colors"><Trash2 className="w-4 h-4" /></button>
                          </div>
                        ))}
                        {customCatalog.length === 0 && <p className="text-center text-gray-600 text-xs py-8 italic">Nenhum produto personalizado.</p>}
                    </div>
                  </div>
              </div>
            )}

            {activeTab === 'manual' && (
              <div className="space-y-6">
                <div className="bg-gray-900 border border-gray-800 rounded-2xl p-6 shadow-xl animate-in fade-in slide-in-from-bottom-2">
                  <h2 className="text-sm font-black text-white flex items-center gap-2 uppercase mb-6"><Plus className="w-4 h-4 text-green-400" /> ADICIONAR AO CARRINHO</h2>
                  <div className="space-y-4">
                    <div className="relative">
                      <Input label="Buscar no Catálogo..." value={searchTerm} onChange={e => { setSearchTerm(e.target.value); setIsSearchOpen(true); }} onFocus={() => setIsSearchOpen(true)} onBlur={() => setTimeout(() => setIsSearchOpen(false), 200)} icon={<Search className="w-4 h-4" />} />
                      {isSearchOpen && searchTerm && (
                        <div className="absolute z-50 w-full mt-1 bg-gray-800 border border-gray-700 rounded-lg shadow-2xl max-h-60 overflow-y-auto">
                          {(debouncedSearchTerm ? fuse.search(debouncedSearchTerm).map(r => r.item) : fullProductsList).map(p => (
                            <button key={p} className="w-full text-left px-4 py-3 text-[10px] text-gray-200 hover:bg-blue-600 font-bold border-b border-gray-700 last:border-0 uppercase" onClick={() => handleSearchSelect(p)}>{p}</button>
                          ))}
                        </div>
                      )}
                    </div>
                    <div className="grid grid-cols-2 gap-4">
                      <Input label="Qtd" type="number" value={selectedQuantity} onChange={e => setSelectedQuantity(e.target.value)} />
                      <Input label="Preço" value={selectedPrice} readOnly icon={<Tag className="w-4 h-4" />} className="bg-gray-800/50" />
                    </div>
                    <button onClick={handleAddProduct} className="w-full bg-blue-600 hover:bg-blue-700 text-white font-black py-4 rounded-xl flex items-center justify-center gap-2 uppercase tracking-widest transition-all"><Plus className="w-5 h-5" /> Adicionar</button>
                  </div>
                </div>
                <div className="bg-gray-900 border border-gray-800 rounded-2xl p-6 shadow-xl animate-in fade-in slide-in-from-bottom-2">
                  <h2 className="text-sm font-black text-white flex items-center gap-2 uppercase mb-6"><User className="w-4 h-4 text-blue-400" /> Dados do Cliente</h2>
                  <div className="space-y-4">
                    <div className="grid grid-cols-2 gap-4">
                        <Input label="Venda" name="saleCode" value={data.saleCode} onChange={handleChange} />
                        <Select label="Vendedor" name="salesperson" value={data.salesperson} onChange={handleChange} options={salespeople} />
                    </div>
                    <Input label="Nome" name="name" value={data.name} onChange={handleChange} />
                    <Input label="CPF/CNPJ" name="cpf" value={data.cpf} onChange={handleChange} />
                    <Input label="Rua" name="street" value={data.street} onChange={handleChange} />
                    <div className="grid grid-cols-2 gap-4">
                        <Input label="Nº" name="number" value={data.number} onChange={handleChange} />
                        <Input label="Bairro" name="neighborhood" value={data.neighborhood} onChange={handleChange} />
                    </div>
                    <div className="grid grid-cols-2 gap-4">
                        <Input label="Complemento" name="complement" value={data.complement} onChange={handleChange} />
                        <Input label="Cidade" name="city" value={data.city} onChange={handleChange} />
                    </div>
                    <Input label="E-mail" name="email" value={data.email} onChange={handleChange} />
                    <div className="grid grid-cols-2 gap-4">
                        <Input label="Contato 1" name="contact1" value={data.contact1} onChange={handleChange} />
                        <Input label="Contato 2" name="contact2" value={data.contact2} onChange={handleChange} />
                    </div>
                    <Select label="Pagamento" name="paymentMethod" value={data.paymentMethod} onChange={handleChange} options={["DINHEIRO", "PIX", "CARTÃO", "OUTROS"]} />
                  </div>
                </div>
              </div>
            )}

            {activeTab === 'import' && (
              <div className="bg-gray-900 border border-gray-800 rounded-2xl p-6 shadow-xl animate-in fade-in">
                  <h2 className="text-lg font-semibold text-white mb-4"><Sparkles className="w-4 h-4 text-purple-400 inline" /> Importar Ficha</h2>
                  <TextArea label="Cole o texto aqui..." value={importText} onChange={e => setImportText(e.target.value)} className="min-h-[200px] mb-4" />
                  <button onClick={handleSmartImport} disabled={isImporting} className="w-full bg-purple-600 hover:bg-purple-700 text-white font-bold py-3 rounded-lg flex items-center justify-center gap-2 transition-all">
                    {isImporting ? <Loader2 className="w-4 h-4 animate-spin" /> : <Sparkles className="w-4 h-4" />} Processar com IA
                  </button>
              </div>
            )}
            {activeTab === 'team' && (
              <div className="bg-gray-900 border border-gray-800 rounded-2xl p-6 shadow-xl">
                  <h2 className="text-lg font-semibold text-white mb-6">Equipe</h2>
                  <div className="flex gap-2 mb-6">
                    <Input label="Novo Vendedor" value={newSalespersonName} onChange={e => setNewSalespersonName(e.target.value)} className="uppercase" />
                    <button onClick={handleAddSalesperson} className="bg-blue-600 p-4 rounded-lg hover:bg-blue-700 transition-colors"><Plus className="w-5 h-5 text-white" /></button>
                  </div>
                  <div className="space-y-2">
                    {salespeople.map(s => (
                      <div key={s} className="flex items-center justify-between bg-gray-800 p-3 rounded-lg border border-gray-700">
                        <span className="font-bold text-gray-200">{s}</span>
                        <button onClick={() => handleRemoveSalesperson(s)} className="text-gray-500 hover:text-red-400 transition-colors"><Trash2 className="w-4 h-4" /></button>
                      </div>
                    ))}
                  </div>
              </div>
            )}
          </div>

          <div className="lg:col-span-7 space-y-6">
            <div className="bg-gray-900 border border-gray-800 rounded-2xl p-4 shadow-xl flex flex-wrap gap-3 items-center justify-between">
              <span className="text-xs font-black uppercase text-gray-500 tracking-widest px-2">Ações Rápidas</span>
              <div className="flex gap-3">
                <button onClick={handleResetData} className="bg-red-600 hover:bg-red-700 text-white font-black px-4 py-2 rounded-lg text-xs uppercase shadow-lg shadow-red-950/20">Novo Cliente</button>
                <button onClick={handleSendWhatsApp} className="bg-green-600 hover:bg-green-700 text-white font-black px-4 py-2 rounded-lg text-xs uppercase shadow-lg shadow-green-950/20">WhatsApp</button>
                <button onClick={handleGeneratePDF} className="bg-blue-600 hover:bg-blue-700 text-white font-black px-4 py-2 rounded-lg text-xs uppercase shadow-lg shadow-blue-950/20">Gerar PDF</button>
              </div>
            </div>

            <div className="bg-gray-900 border border-gray-800 rounded-2xl p-8 shadow-2xl flex justify-center overflow-x-auto min-h-[900px]">
                {/* PREVIEW EXATAMENTE COMO ESTÁ NO PDF - ALTA FIDELIDADE */}
                <div className="bg-white text-gray-900 p-8 rounded shadow-2xl w-[210mm] flex flex-col font-sans scale-[0.6] sm:scale-[0.8] origin-top md:scale-100">
                    {/* Header Azul - Igual ao PDF */}
                    <div className="bg-[#1e40af] text-white p-6 -mx-8 -mt-8 mb-6 flex justify-between items-start">
                       <div className="flex flex-col">
                           <h1 className="font-serif font-bold text-3xl italic">BelConfort</h1>
                           <span className="text-[9px] tracking-[0.4em] font-sans font-bold uppercase">Camas e Móveis</span>
                       </div>
                       <div className="flex items-center gap-4">
                           <div className="text-right text-[9px] font-medium opacity-80 leading-tight">
                               <p className="font-bold text-[11px] mb-1 text-white">CNPJ 60.190.028/0001-60</p>
                               <p>RUA B, 103C, CASTANHEIRA - BELEM/PA</p>
                               <p>belconfortcamasemoveis@gmail.com</p>
                               <p>(91) 99381-2592</p>
                           </div>
                           <div className="bg-white p-1 rounded">
                              <QrCode className="w-14 h-14 text-[#1e40af]" />
                           </div>
                       </div>
                    </div>

                    <div className="text-center mb-6">
                        <h2 className="text-lg font-black text-gray-800 uppercase tracking-widest">COMPROVANTE DE COMPRA</h2>
                        <p className="text-[10px] text-gray-400 italic">Emissão: {new Date().toLocaleDateString('pt-BR')} às {new Date().toLocaleTimeString('pt-BR', { hour: '2-digit', minute: '2-digit' })}</p>
                    </div>

                    {/* Grid de Dados do Cliente - Layout Exato do PDF */}
                    <div className="border border-gray-300 mb-6 text-[9px] rounded overflow-hidden">
                        {/* Linha 1 */}
                        <div className="grid grid-cols-[25%_50%_25%] border-b border-gray-300">
                            <PreviewCell label="DATA DO PEDIDO" value={data.date || new Date().toLocaleDateString('pt-BR')} className="border-r border-gray-300" />
                            <PreviewCell label="CLIENTE" value={data.name} className="border-r border-gray-300" />
                            <PreviewCell label="CPF/CNPJ" value={data.cpf} />
                        </div>
                        {/* Linha 2 */}
                        <div className="grid grid-cols-[40%_10%_15%_15%_20%] border-b border-gray-300">
                            <PreviewCell label="RUA" value={data.street} className="border-r border-gray-300" />
                            <PreviewCell label="Nº" value={data.number} className="border-r border-gray-300" />
                            <PreviewCell label="COMPLEMENTO" value={data.complement} className="border-r border-gray-300" />
                            <PreviewCell label="BAIRRO" value={data.neighborhood} className="border-r border-gray-300" />
                            <PreviewCell label="CIDADE" value={data.city} />
                        </div>
                        {/* Linha 3 */}
                        <div className="grid grid-cols-[50%_50%]">
                            <PreviewCell label="E-MAIL" value={data.email} className="border-r border-gray-300" />
                            <PreviewCell label="CONTATOS" value={[data.contact1, data.contact2].filter(Boolean).join(' / ')} />
                        </div>
                    </div>

                    {/* Tabela de Itens - Cabeçalho Azul e Barcode */}
                    <div className="flex-grow">
                        <div className="grid grid-cols-[60px_1fr_40px_70px_70px] bg-gray-50 border-y border-gray-300 text-[8px] font-black text-[#1e40af] py-2 px-3 uppercase tracking-wider">
                            <span>CÓD</span><span>DESCRIÇÃO DO PRODUTO</span><span className="text-center">QTD</span><span className="text-right">UNITÁRIO</span><span className="text-right">TOTAL</span>
                        </div>
                        {data.products.map((p, i) => (
                            <div key={i} className="grid grid-cols-[60px_1fr_40px_70px_70px] text-[10px] py-3 px-3 border-b border-gray-100 items-center">
                                <div className="flex flex-col items-start gap-1">
                                    <span className="font-bold text-[9px]">{p.code || '-'}</span>
                                    <BarcodePreview code={p.code || ''} />
                                </div>
                                <div className="flex flex-col">
                                    <span className="font-bold uppercase text-gray-800 leading-tight">{p.name}</span>
