                        {/* Carimbo Virtual */}
                        <div className="border-2 border-[#1e3a8a] p-2 flex flex-col items-center opacity-80 rotate-2 select-none h-min">
                            <span className="text-[8px] font-black text-[#1e3a8a]">60.190.028/0001-60</span>
                            <span className="text-[6px] font-bold text-[#1e3a8a]">BELCONFORT CAMAS E MÓVEIS</span>
                            <span className="text-[5px] text-[#1e3a8a] font-bold">RUA B, 103C, CASTANHEIRA</span>
                            <span className="text-[5px] text-[#1e3a8a] font-bold">BELEM - PA</span>
                        </div>
                    </div>

                    <div className="mt-auto pt-6 text-[7px] text-center text-gray-300 font-bold italic uppercase tracking-widest opacity-50">
                        Documento gerado pelo Ecosistema Belconfort
                    </div>
                </div>
            </div>
          </div>
        </div>
      </main>
    </div>
  );
}

